-- GENERATED by tools/build-migrations.mjs from supabase/migrations/. Do not edit — run
-- `npm run build:migrations` instead (.claude/instruction_mds/migrations.md).
--
-- Every migration, oldest first. Each one is re-runnable, so this whole file can be pasted into the
-- dashboard's SQL Editor to build the schema on a fresh project.

-- ===== 20260902000002_profiles.sql =====

-- One row per user, created by a trigger so a profile always exists by the time the app reads
-- one, and deleted by the cascade when the account goes.

-- Holds functions that must never be reachable over HTTP: PostgREST publishes `public` (and
-- `graphql_public`) and nothing else, so a function in here has no /rest/v1/rpc/ URL to attack.
create schema if not exists private;

create table if not exists public.profiles (
  -- Not a key this schema chooses: it is auth.users.id. Random uuids fragment an index, but that
  -- trade was made in auth.users, and matching it is what lets `on delete cascade` do the cleanup.
  id uuid primary key references auth.users (id) on delete cascade,

  -- No `email` column on purpose. auth.users.email is the source of truth and the client already
  -- holds it as session.user.email; a copy here goes stale the moment someone changes their
  -- address, and keeping it in step needs a second trigger that nobody remembers to write.
  display_name text,
  avatar_url text,
  created_at timestamptz not null default now()
);

-- Every table you add needs this line of its own. The next migration tries to install an event
-- trigger that would also catch it, but that needs superuser and hosted Supabase's `postgres` role is
-- not one — there it only warns and the trigger never exists (verified 2026-09-13), so it is no
-- substitute for writing the line. Without it PostgREST serves the whole table to anyone holding the
-- publishable key, which ships in the app bundle. The dashboard's Security Advisor flags the tables
-- that are missing it.
alter table public.profiles enable row level security;

-- Deliberately NOT `force row level security`, which is otherwise the stricter default worth
-- reaching for. Forcing it subjects the table owner to the policies too, and handle_new_user below
-- inserts as the owner during signup — a moment when there is no JWT, so auth.uid() is null and
-- profiles_insert_own would reject the row that signup exists to create.

-- Every policy is scoped `to authenticated` so it is never even evaluated for anon, and every
-- auth.uid() is wrapped in a select. Unwrapped, it is called once per row scanned; wrapped, the
-- planner runs it once as an InitPlan and reuses the result.
drop policy if exists profiles_select_own on public.profiles;
create policy profiles_select_own on public.profiles
  for select to authenticated
  using ((select auth.uid()) = id);

drop policy if exists profiles_insert_own on public.profiles;
create policy profiles_insert_own on public.profiles
  for insert to authenticated
  with check ((select auth.uid()) = id);

-- `using` decides which rows may be updated, `with check` what they may be updated *to*. Without
-- the second one a user could hand their row to somebody else by rewriting its id.
drop policy if exists profiles_update_own on public.profiles;
create policy profiles_update_own on public.profiles
  for update to authenticated
  using ((select auth.uid()) = id)
  with check ((select auth.uid()) = id);

-- No delete policy, so no client can delete a profile directly. The row goes when the account
-- does, through the cascade on auth.users that delete_current_user below triggers.

-- No index on id: the primary key already is one.


-- Creates the profile row for a new signup.
--
-- security definer because the insert has to bypass RLS — see the note above about auth.uid()
-- being null inside the signup transaction — and because the caller here is GoTrue, not the user.
create or replace function private.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  insert into public.profiles (id, display_name, avatar_url)
  values (
    new.id,
    -- Google and Facebook both land here through signInWithIdToken / the browser flow, and both
    -- populate these two keys. nullif keeps an empty string from masquerading as a set name.
    -- The jsonb ->> operator is in pg_catalog, so it still resolves under the empty search_path.
    nullif(new.raw_user_meta_data ->> 'full_name', ''),
    nullif(new.raw_user_meta_data ->> 'avatar_url', '')
  )
  on conflict (id) do nothing;
  return new;
end;
$$;

revoke execute on function private.handle_new_user() from public, anon, authenticated, service_role;

-- Revoking EXECUTE does not stop this. Postgres checks EXECUTE on a trigger function when the
-- trigger is created, not each time it fires, so the trigger keeps working while the function
-- stays uncallable by hand.
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function private.handle_new_user();


-- Self-service account deletion, which the App Store requires of any app that can create an
-- account (Guideline 5.1.1(v)). Called from deleteAccount() in src/lib/auth.ts.
--
-- This one is in `public` because it is meant to be reachable — it is the app's own API, and
-- PostgREST only publishes `public`. Which is exactly why the grants below are not optional.
create or replace function public.delete_current_user()
returns void
language sql
security definer
set search_path = ''
as $$
  -- The only row this can ever touch is the caller's own. For an unauthenticated caller auth.uid()
  -- is null and `id = null` matches nothing, so the failure mode is deleting zero rows; the grant
  -- below is what actually keeps anon out. public.profiles goes with it through the cascade.
  delete from auth.users where id = (select auth.uid());
$$;

-- Without this, `create function` in a Supabase project leaves the function callable at
-- POST /rest/v1/rpc/delete_current_user by anyone holding the anon key — which ships inside the
-- app binary. Supabase's default privileges grant EXECUTE to anon, authenticated and service_role
-- directly, so all three have to be named; revoking from PUBLIC alone would not reach them.
revoke execute on function public.delete_current_user() from public, anon, authenticated, service_role;
grant execute on function public.delete_current_user() to authenticated;


-- ===== 20260902000003_rls_auto_enable.sql =====

-- Enables RLS automatically on every table created in `public` from here on.
--
-- This runs. It is a normal migration and `supabase db push` applies it.
--
--
-- What it does
--
-- Installs a DDL event trigger that runs `alter table ... enable row level security` on every table
-- created in `public` from then on. Forgetting that on one table is the most common way a Supabase
-- project leaks data: PostgREST publishes the table over HTTP the moment it exists, the publishable
-- key ships inside the app bundle where anyone can read it out, and with no policy in force every
-- row is world-readable.
--
--
-- It is a safety net, not the mechanism
--
-- Keep writing `alter table ... enable row level security` explicitly in every migration. Two
-- reasons this trigger cannot be relied on alone:
--
--   1. It needs superuser to install (see the DO block at the bottom), and on hosted Supabase it
--      does NOT install. The project's `postgres` role is not a superuser (`rolsuper` is false), so
--      `create event trigger` fails with `permission denied to create event trigger` — verified on
--      this project's hosted database on 2026-09-13. The block turns that into a warning, so
--      `supabase db push` succeeds, the SQL Editor reports "Success", and the trigger is simply not
--      there. private.rls_auto_enable() below is still created, with nothing calling it. The
--      trigger only exists on a local `supabase start` stack, so on a hosted project the explicit
--      line is the only thing that turns RLS on.
--   2. It is invisible. `\d your_table` does not mention it, the migration that created that table
--      does not mention it, and nothing leads a reader from an unexpectedly empty result back to
--      this file.
--
-- RLS with no policies is deny-all, so when it does fire the failure mode is a query returning
-- nothing — loud, and one `create policy` away from fixed.
--
--
-- What still reports the gap
--
-- The dashboard's Security Advisor (Advisors -> Security) reports `rls_disabled_in_public` for any
-- table this missed. `supabase db lint` is NOT this — that command only type-checks plpgsql.

create schema if not exists private;

-- The function lives in `private`, not `public`. PostgREST only publishes `public` (and
-- `graphql_public`), so nothing in here has a /rest/v1/rpc/ URL at all. The revoke below is a
-- second lock on the same door.
create or replace function private.rls_auto_enable()
returns event_trigger
language plpgsql
security definer
-- Pinned, and the body fully qualified because of it. An unqualified name inside a security
-- definer function resolves against the *caller's* search_path, so a caller who creates their own
-- `format` or their own table and points the path at it gets that object executed with this
-- function's owner privileges. Empty is safe for the calls below: pg_catalog is searched
-- implicitly even when it is not on the path.
set search_path = ''
as $$
declare
  cmd record;
begin
  for cmd in
    select *
    from pg_catalog.pg_event_trigger_ddl_commands()
    where object_type in ('table', 'partitioned table')
      and schema_name = 'public'
  loop
    begin
      -- object_identity arrives already schema-qualified and quoted, so %s is right here and %I
      -- would quote it a second time.
      execute pg_catalog.format('alter table %s enable row level security', cmd.object_identity);
    exception
      -- An event trigger that raises aborts the CREATE TABLE that fired it. A table that resists
      -- RLS is worth a warning, not a migration that cannot run.
      when others then
        raise warning 'rls_auto_enable: could not enable RLS on %', cmd.object_identity;
    end;
  end loop;
end;
$$;

-- Not redundant with the schema choice. Supabase ships default privileges that grant EXECUTE on
-- new functions to anon, authenticated and service_role *directly* — not through PUBLIC — so
-- revoking from PUBLIC alone would leave three live grants behind.
revoke execute on function private.rls_auto_enable() from public, anon, authenticated, service_role;

-- CREATE EVENT TRIGGER requires superuser. The local `supabase start` stack has it; hosted Supabase's
-- `postgres` role does not, so on a hosted project this block always lands in the exception branch.
-- That must not take the whole migration down: every table's own migration enables RLS explicitly,
-- so this is defence in depth where it installs, not the only defence.
do $$
begin
  execute 'drop event trigger if exists ensure_rls';
  execute 'create event trigger ensure_rls on ddl_command_end
             when tag in (''CREATE TABLE'', ''CREATE TABLE AS'', ''SELECT INTO'')
             execute function private.rls_auto_enable()';
exception
  when insufficient_privilege then
    raise warning
      'ensure_rls not installed: creating an event trigger needs superuser. Every table still sets RLS explicitly.';
end;
$$;


-- ===== 20260908000000_drop_legacy_catalog_functions.sql =====

-- Drop the leftover book-catalog functions.
--
-- The hosted project this repo points at was previously used by an unrelated library
-- catalog app. Its tables are already gone, but nine functions survived in `public`
-- with no caller and no dependent object: `pg_trigger` holds only this project's own
-- `on_auth_user_created`, and `fn_set_updated_at` is attached to nothing.
--
-- They are not dead weight only. `public` is the schema PostgREST publishes, so each
-- one was a live `/rest/v1/rpc/<name>` URL reachable with the publishable key that
-- ships inside the app bundle. Three were `security definer` with `execute` still
-- granted to `anon`:
--
--   * `verify_user_password` (both overloads) answered password guesses without a
--     session — an unauthenticated credential-testing endpoint.
--   * `insert_book_encrypted` wrote rows as the owner.
--
-- None of the nine pinned `search_path`, so an unqualified name in the body resolved
-- against the caller's — the escalation CLAUDE.md section 6.2 rule 2 describes.
--
-- `if exists` because a clone pointed at a fresh Supabase project never had these,
-- and `supabase db push` has to succeed there too. No `cascade`: if some object does
-- turn out to depend on one of these, this migration should fail loudly rather than
-- take that object with it.
--
-- No revert file (docs/migrations.md rule 2): the bodies of what this drops are not in
-- the repo, and restoring them would reopen the endpoints described above.
-- no-revert: drop-only; its revert would restore leftover functions from an unrelated project

drop function if exists public.verify_user_password(p_email text, p_password text, p_enc_key text);
drop function if exists public.verify_user_password(p_email_fingerprint text, p_password text);
drop function if exists public.insert_book_encrypted(
  p_enc_key text, p_title text, p_responsibility text, p_variant_title text,
  p_parallel_title text, p_main_creator text, p_contributors text, p_corporate text,
  p_place_of_publication text, p_publisher text, p_date_of_publication text,
  p_extent_of_text text, p_edition text, p_illustration text, p_series text,
  p_isbn text, p_subject_typical text, p_subject_personal text,
  p_call_number_prefix text, p_call_number text, p_material_types text[],
  p_accession text, p_language text, p_library_location text,
  p_electronic_access text, p_cover_image_file text, p_vol_copy integer,
  p_entered_by text, p_date_entered date, p_update_date date, p_vocabulary text,
  p_localization text, p_collection_types text[]
);
drop function if exists public.encrypt_field(plaintext text, enc_key text);
drop function if exists public.decrypt_field(ciphertext bytea, enc_key text);
drop function if exists public.hash_password(plain text);
drop function if exists public.verify_password(plain text, stored_hash text);
drop function if exists public.sha256_hex(val text);
drop function if exists public.fn_set_updated_at();


-- ===== 20260908131200_merchants.sql =====

-- The tenant table. A merchant is the business whose rows are being protected; a user account is a
-- person. Today one merchant has exactly one user, and `merchants.owner_id` *is* the membership —
-- see docs/tenancy.md §3 for why `merchant_members` is deliberately not built yet.
--
-- This is also the answer to the open question in docs/tenancy.md §5, "who creates the merchant
-- row?": not a trigger. An explicit onboarding step — CreateSystemModal in
-- src/features/merchants/ — because a staff member joining an existing merchant must not silently
-- create a second one.

-- Already created by 20260902000002_profiles.sql. Repeated because a migration that depends on a
-- schema should say so rather than inherit it by file ordering.
create schema if not exists private;

-- An enum rather than `text` + a check constraint. Both cost one migration to add a value and both
-- need the same data migration to remove one, so the tie is broken by what reaches the client:
-- an enum generates a real union in src/lib/database.types.ts, which is what lets
-- CATEGORY_META[row.category] compile with no type assertion. `text` generates `string`, which
-- forces exactly the assertion .oxlintrc.json rejects (require-safety-comment-for-type-assertion,
-- no-unsafe-dictionary-type).
--
-- Adding a category later is `alter type public.store_category add value '…'` in a migration of its
-- own: Postgres will not let the same transaction use a value it just added.
do $$
begin
  if not exists (
    select 1 from pg_type t
    join pg_namespace n on n.oid = t.typnamespace
    where t.typname = 'store_category' and n.nspname = 'public'
  ) then
    create type public.store_category as enum (
      'restaurant', 'cafe', 'clothing', 'grocery', 'bakery',
      'electronics', 'pharmacy', 'bookstore', 'fitness', 'other'
    );
  end if;
end
$$;

create table if not exists public.merchants (
  id uuid primary key default gen_random_uuid(),

  -- The cascade is what makes public.delete_current_user() complete: deleting the auth.users row
  -- takes the profile and every merchant with it, so account deletion needs no extra statement.
  owner_id uuid not null references auth.users (id) on delete cascade,

  name text not null,
  description text,
  category public.store_category not null,
  created_at timestamptz not null default now(),

  -- btrim so a name of pure whitespace fails. The 255 on description is the number the
  -- CreateSystemModal counter shows the user; the same bound lives in
  -- src/features/merchants/schema.ts so the form reports it before a round trip, and here so the
  -- database is the one that actually enforces it.
  constraint merchants_name_length check (length(btrim(name)) between 1 and 80),
  constraint merchants_description_length check (description is null or length(description) <= 255)
);

-- Its own line, per the note in 20260902000002_profiles.sql. The event trigger in
-- 20260902000003_rls_auto_enable.sql would also catch this table where it installs, but installing it
-- needs superuser — so on hosted Supabase it is not there (verified 2026-09-13), and this line is the
-- only thing that turns RLS on.
alter table public.merchants enable row level security;

-- Not covered by the primary key. private.current_merchant_ids() filters on this column, and once
-- business tables exist that call runs once per statement in every one of their policies.
create index if not exists merchants_owner_id_idx on public.merchants (owner_id);

-- These policies key on owner_id, NOT on private.current_merchant_ids(), and that is not an
-- oversight. docs/tenancy.md rule 3 governs *business* tables — the ones carrying a merchant_id
-- column. This is the tenant root itself, and routing its policies through the function that reads
-- the tenant root is the self-reference §3 flags under "the recursion trap".
--
-- When merchant_members arrives, only merchants_select_own changes:
--   using (id in (select private.current_merchant_ids()))
-- The three write policies stay on owner_id, and no business table moves.
drop policy if exists merchants_select_own on public.merchants;
create policy merchants_select_own on public.merchants
  for select to authenticated
  using ((select auth.uid()) = owner_id);

drop policy if exists merchants_insert_own on public.merchants;
create policy merchants_insert_own on public.merchants
  for insert to authenticated
  with check ((select auth.uid()) = owner_id);

-- Both clauses, for the same reason profiles_update_own carries both: `using` picks the rows,
-- `with check` picks what they may become. Without the second, a merchant can be handed to another
-- account by rewriting owner_id.
drop policy if exists merchants_update_own on public.merchants;
create policy merchants_update_own on public.merchants
  for update to authenticated
  using ((select auth.uid()) = owner_id)
  with check ((select auth.uid()) = owner_id);

-- Unlike profiles, merchants gets a delete policy: a user removing one of their own businesses is
-- an ordinary action, not account deletion.
drop policy if exists merchants_delete_own on public.merchants;
create policy merchants_delete_own on public.merchants
  for delete to authenticated
  using ((select auth.uid()) = owner_id);


-- The seam, and it ships with no caller on purpose.
--
-- Every business table added later gets policies of the shape
--   using (merchant_id in (select private.current_merchant_ids()))
-- and staff support then arrives by rewriting this function's body alone — zero policy rewrites,
-- zero table alterations. Writing it now is what stops the first business table shipping an
-- `auth.uid() = owner_id` policy "just for now", which is the rewrite-every-table cost
-- docs/tenancy.md §2 exists to avoid.
--
-- All three requirements from CLAUDE.md §6.2 are met: it lives in `private` so PostgREST publishes
-- no /rest/v1/rpc/ URL for it; search_path is pinned empty with a fully-qualified body, so a caller
-- cannot point an unqualified name at their own table and have it run as the owner; and the
-- (select auth.uid()) inside means it can only ever answer for its caller, however it is reached.
--
-- `stable` lets the planner call it once per statement instead of once per row.
create or replace function private.current_merchant_ids()
returns setof uuid
language sql
security definer
stable
set search_path = ''
as $$
  select m.id from public.merchants m where m.owner_id = (select auth.uid());
$$;

-- PUBLIC alone would not be enough: Supabase's default privileges grant EXECUTE on new functions to
-- anon, authenticated and service_role *directly*, so revoking from PUBLIC leaves three live grants
-- behind. All four names, every time.
revoke execute on function private.current_merchant_ids()
  from public, anon, authenticated, service_role;


-- ===== 20260910000000_merchants_contact_and_address.sql =====

-- CreateSystemModal revamp (revamps/Thu_09-10-2026_13.59.58.10): the wizard now collects seven
-- fields instead of four. Three of them land on public.merchants.
--
-- Every statement here is re-runnable, like the rest of supabase/migrations — `rename column` is
-- the one that is not idempotent on its own, so each is guarded by a catalog lookup rather than
-- `if not exists`, which ALTER ... RENAME does not accept.

-- 1. Store Description became Store Address.
--
-- A rename, not "add address, leave description behind". The field did not gain a sibling, it
-- changed meaning: the same one free-text box under the same 255 counter, now asking for where the
-- store is. Adding a column would leave `description` in the row shape forever, readable by
-- PostgREST, generated into database.types.ts, and answering "which one is live?" wrong for every
-- reader after today. A rename keeps the data and leaves nothing dead.
do $$
begin
  if exists (
    select 1 from information_schema.columns
    where table_schema = 'public' and table_name = 'merchants' and column_name = 'description'
  ) then
    alter table public.merchants rename column description to address;
    -- The constraint name is part of the error message a violation prints. Left as
    -- merchants_description_length it would name a column that no longer exists.
    alter table public.merchants rename constraint merchants_description_length to merchants_address_length;
  end if;
end
$$;

-- 2. The business contact email.
--
-- NOT a mirror of auth.users.email, and deliberately not on public.profiles. The reasoning that
-- keeps an email column off profiles (ARCHITECTURE.md — auth.users.email is the source of truth,
-- the client already holds it as session.user.email, a copy goes stale on the first address change)
-- is untouched by this: that is the *person's* sign-in address, this is the *business's* published
-- contact. They can differ, and one owner with two merchants can publish two of them, which is only
-- expressible on this table.
--
-- ponytail: nullable, because every merchant row that already exists was created before this field
-- did and there is nothing true to backfill them with. The form requires it for new rows
-- (src/features/merchants/schema.ts). Tighten to `not null` once the existing rows have one.
alter table public.merchants add column if not exists contact_email text;

-- 3. The phone number, stored as one E.164 string rather than a (dial code, national number) pair.
--
-- The wizard composes it from a country picker and one editable input, but what is worth keeping is
-- the number a person would dial. Splitting it across two columns would need both to be read and
-- rejoined at every call site, and the split is recoverable from the string anyway.
alter table public.merchants add column if not exists phone text;

-- Client-side Zod reports these before a round trip; these are what actually enforce them. Both
-- allow null, so they constrain the shape of a value without making the column required.
--
-- The email check is a length bound plus "has an @ with something before it" — deliberately not an
-- RFC 5322 regex. A regex strict enough to be worth writing rejects addresses that deliver, and one
-- loose enough not to is this check with more characters.
do $$
begin
  if not exists (
    select 1 from pg_constraint where conname = 'merchants_contact_email_shape'
  ) then
    alter table public.merchants add constraint merchants_contact_email_shape
      check (
        contact_email is null
        or (length(contact_email) between 3 and 254 and position('@' in contact_email) > 1)
      );
  end if;

  -- E.164: a leading +, then 7 to 15 digits. Anything the user typed as spacing or punctuation is
  -- stripped on the client before it gets here, so this rejects a malformed number rather than a
  -- differently formatted one.
  if not exists (
    select 1 from pg_constraint where conname = 'merchants_phone_shape'
  ) then
    alter table public.merchants add constraint merchants_phone_shape
      check (phone is null or phone ~ '^\+[0-9]{7,15}$');
  end if;
end
$$;

-- No RLS line and no policies. This migration adds columns to a table that already has both, and
-- the four merchants_*_own policies key on owner_id — which is row-level, so a new column is
-- covered by them the moment it exists. A new *table* would need its own
-- `alter table … enable row level security` (CLAUDE.md §6.1); an altered one does not.


-- ===== 20260914092147_products.sql =====

-- Products: the first business table, behind the Assets screen, with the three
-- per-merchant lookups its form picks from — categories, tax classes, suppliers — and the six child
-- sets a product carries: rate tiers, operating hours, variant attributes, variants, bundle
-- components and custom fields.
--
-- Every table here carries a not-null merchant_id from this first migration (docs/tenancy.md rule 2)
-- and every policy keys on private.current_merchant_ids(), which gets its first caller today
-- (docs/tenancy.md rule 3). Re-runnable, like the rest of supabase/migrations.

create schema if not exists private;

-- 0. Let the policies below actually call the seam.
--
-- 20260908131200_merchants.sql revoked EXECUTE on current_merchant_ids() from authenticated, and
-- nothing granted USAGE on `private`. That was harmless while the function had no caller, but a
-- policy expression runs with the privileges of the role that issued the query — so every policy on
-- every table below would fail with "permission denied for schema private" (verified on the hosted
-- project 2026-09-14: both privileges false).
--
-- Granting them does not publish anything. PostgREST exposes `public` only, so a function in `private`
-- still has no /rest/v1/rpc/ URL, and the function answers for (select auth.uid()) alone — the other
-- two requirements of CLAUDE.md §6.2 carry the guarantee. The other functions in `private` keep their
-- EXECUTE revoked, so USAGE on the schema reaches none of them.
grant usage on schema private to authenticated;
grant execute on function private.current_merchant_ids() to authenticated;


-- 1. The currency a merchant's prices are shown in. ISO 4217 code, formatted on the client with
-- Intl.NumberFormat. Defaults to PHP because every existing merchant was set up with the Philippine
-- dial code first in the wizard; there is no setting UI for it yet.
alter table public.merchants add column if not exists currency text not null default 'PHP';

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'merchants_currency_shape') then
    alter table public.merchants add constraint merchants_currency_shape check (currency ~ '^[A-Z]{3}$');
  end if;
end
$$;


-- 2. Enums. Each one generates a real union in src/lib/database.types.ts, which is what lets the form
-- index its label maps with no type assertion (the same trade store_category made). Adding a value
-- later is `alter type … add value` in a migration of its own.
do $$
begin
  if to_regtype('public.product_type') is null then
    create type public.product_type as enum ('stock', 'rental', 'bookable', 'flat');
  end if;
  if to_regtype('public.product_status') is null then
    create type public.product_status as enum ('draft', 'active', 'inactive', 'archived');
  end if;
  -- One list for Unit of Measure, Pricing Unit, purchase/usage units and duration units. Chosen fixed
  -- by the human over merchant-defined units, whose conversion factors between arbitrary custom
  -- units have no sensible meaning.
  if to_regtype('public.measure_unit') is null then
    create type public.measure_unit as enum (
      'piece', 'box', 'pack', 'kg', 'g', 'l', 'ml',
      'minute', 'hour', 'day', 'week', 'month', 'night', 'session'
    );
  end if;
  if to_regtype('public.duration_mode') is null then
    create type public.duration_mode as enum ('fixed_slot', 'flexible_range');
  end if;
  if to_regtype('public.rate_period') is null then
    create type public.rate_period as enum ('hour', 'day', 'week', 'month', 'night');
  end if;
  if to_regtype('public.custom_field_kind') is null then
    create type public.custom_field_kind as enum ('text', 'number', 'date', 'boolean');
  end if;
end
$$;


-- 3. Lookups.
--
-- Each has unique (id, merchant_id). That pair is what the product's foreign keys reference, so a
-- product can only ever point at a category, tax class or supplier of its own merchant — enforced by
-- the key itself, not by a policy that has to be remembered.

-- A subcategory is a category with a parent. ponytail: one level deep by convention — the picker only
-- offers top-level parents; a trigger enforcing depth is the upgrade if nesting ever appears.
create table if not exists public.product_categories (
  id uuid primary key default gen_random_uuid(),
  merchant_id uuid not null references public.merchants (id) on delete cascade,
  parent_id uuid,
  name text not null,
  created_at timestamptz not null default now(),

  constraint product_categories_id_merchant unique (id, merchant_id),
  constraint product_categories_parent_fk foreign key (parent_id, merchant_id)
    references public.product_categories (id, merchant_id) on delete cascade,
  constraint product_categories_not_own_parent check (parent_id is null or parent_id <> id),
  constraint product_categories_name_length check (length(btrim(name)) between 1 and 60),
  -- nulls not distinct, so two top-level categories (parent_id null) cannot share a name either.
  constraint product_categories_name_unique unique nulls not distinct (merchant_id, parent_id, name)
);

alter table public.product_categories enable row level security;
create index if not exists product_categories_merchant_id_idx on public.product_categories (merchant_id);
create index if not exists product_categories_parent_id_idx on public.product_categories (parent_id);

create table if not exists public.tax_classes (
  id uuid primary key default gen_random_uuid(),
  merchant_id uuid not null references public.merchants (id) on delete cascade,
  name text not null,
  rate numeric(5, 2) not null default 0,
  created_at timestamptz not null default now(),

  constraint tax_classes_id_merchant unique (id, merchant_id),
  constraint tax_classes_name_length check (length(btrim(name)) between 1 and 60),
  constraint tax_classes_rate_range check (rate between 0 and 100),
  constraint tax_classes_name_unique unique (merchant_id, name)
);

alter table public.tax_classes enable row level security;
create index if not exists tax_classes_merchant_id_idx on public.tax_classes (merchant_id);

create table if not exists public.suppliers (
  id uuid primary key default gen_random_uuid(),
  merchant_id uuid not null references public.merchants (id) on delete cascade,
  name text not null,
  contact text,
  created_at timestamptz not null default now(),

  constraint suppliers_id_merchant unique (id, merchant_id),
  constraint suppliers_name_length check (length(btrim(name)) between 1 and 80),
  constraint suppliers_contact_length check (contact is null or length(contact) <= 255)
);

alter table public.suppliers enable row level security;
create index if not exists suppliers_merchant_id_idx on public.suppliers (merchant_id);


-- 4. Products.
--
-- One wide row rather than a table per type. The four types share General, Pricing, Media and
-- Advanced, and differ only in which of the inventory and availability columns are meaningful; a table
-- per type would need a union to list products at all. Columns a type does not use stay null.
--
-- Foreign keys use the default NO ACTION rather than RESTRICT on purpose: deleting a merchant cascades
-- to both its categories and its products in one statement, and RESTRICT checks immediately — before
-- the cascade has removed the products — where NO ACTION waits for the end of the statement.
create table if not exists public.products (
  id uuid primary key default gen_random_uuid(),
  merchant_id uuid not null references public.merchants (id) on delete cascade,

  -- General
  type public.product_type not null,
  name text not null,
  category_id uuid not null,
  subcategory_id uuid,
  sku text,
  barcode text,
  description text,
  tags text[] not null default '{}',
  status public.product_status not null default 'draft',
  sold_directly boolean not null default true,

  -- Pricing
  selling_price numeric(12, 2),
  cost_price numeric(12, 2),
  pricing_unit public.measure_unit,
  tax_class_id uuid,
  discountable boolean not null default true,
  deposit_amount numeric(12, 2),
  late_fee_per_hour numeric(12, 2),
  cancellation_fee numeric(12, 2),
  extra_unit_fee numeric(12, 2),

  -- Inventory (stock, rental)
  uom public.measure_unit,
  track_inventory boolean not null default true,
  qty_on_hand numeric(12, 3),
  reorder_threshold numeric(12, 3),
  reorder_qty numeric(12, 3),
  max_stock numeric(12, 3),
  storage_location text,
  supplier_id uuid,
  supplier_item_code text,
  lead_time_days integer,
  batch_tracking boolean not null default false,
  perishable boolean not null default false,
  shelf_life_days integer,
  expiry_date date,
  expiry_alert_days integer,
  purchase_unit public.measure_unit,
  usage_unit public.measure_unit,
  conversion_factor numeric(14, 4),

  -- Availability (rental, bookable)
  total_units integer,
  capacity_per_unit integer,
  duration_mode public.duration_mode,
  default_start_time time,
  default_end_time time,
  min_duration numeric(8, 2),
  min_duration_unit public.measure_unit,
  max_duration numeric(8, 2),
  max_duration_unit public.measure_unit,
  buffer_minutes integer,
  advance_window_days integer,
  blackout_dates date[] not null default '{}',
  overbooking_allowed boolean not null default false,

  -- Variants, recipe / bundle, advanced
  has_variants boolean not null default false,
  is_composite boolean not null default false,
  internal_notes text,

  -- The file name the Image-Pipeline brief stores (context/Image-Pipeline/packages.md §5). Written from
  -- this first migration so adding photos later is code only; nothing writes it yet.
  image_file text,

  -- PostgREST can filter a column against a value but not against another column, so "Low stock only"
  -- needs this spelled out. Stored, so the filter is a plain index-free equality on a small table.
  is_low_stock boolean generated always as (
    coalesce(track_inventory and qty_on_hand <= reorder_threshold, false)
  ) stored,

  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),

  constraint products_id_merchant unique (id, merchant_id),
  constraint products_sku_unique unique (merchant_id, sku),
  constraint products_category_fk foreign key (category_id, merchant_id)
    references public.product_categories (id, merchant_id),
  constraint products_subcategory_fk foreign key (subcategory_id, merchant_id)
    references public.product_categories (id, merchant_id),
  -- The column list on SET NULL (Postgres 15+) nulls only the pointer. Without it the whole key pair
  -- would be nulled, merchant_id included, which the not-null constraint rejects.
  constraint products_tax_class_fk foreign key (tax_class_id, merchant_id)
    references public.tax_classes (id, merchant_id) on delete set null (tax_class_id),
  constraint products_supplier_fk foreign key (supplier_id, merchant_id)
    references public.suppliers (id, merchant_id) on delete set null (supplier_id),

  constraint products_name_length check (length(btrim(name)) between 1 and 120),
  constraint products_description_length check (description is null or length(description) <= 2000),
  constraint products_code_length check (
    (sku is null or length(sku) between 1 and 64) and (barcode is null or length(barcode) between 1 and 64)
  ),
  -- The spec's "Selling Price required if sold directly". A draft may be saved half-filled.
  constraint products_price_when_sold check (not sold_directly or status = 'draft' or selling_price is not null),
  constraint products_amounts_non_negative check (
    coalesce(selling_price, 0) >= 0 and coalesce(cost_price, 0) >= 0
    and coalesce(deposit_amount, 0) >= 0 and coalesce(late_fee_per_hour, 0) >= 0
    and coalesce(cancellation_fee, 0) >= 0 and coalesce(extra_unit_fee, 0) >= 0
    and coalesce(reorder_threshold, 0) >= 0 and coalesce(reorder_qty, 0) >= 0
    and coalesce(max_stock, 0) >= 0 and coalesce(total_units, 0) >= 0
    and coalesce(capacity_per_unit, 0) >= 0 and coalesce(buffer_minutes, 0) >= 0
    and coalesce(advance_window_days, 0) >= 0 and coalesce(lead_time_days, 0) >= 0
    and coalesce(shelf_life_days, 0) >= 0 and coalesce(expiry_alert_days, 0) >= 0
    and coalesce(min_duration, 0) >= 0 and coalesce(max_duration, 0) >= 0
  ),
  constraint products_conversion_positive check (conversion_factor is null or conversion_factor > 0)
);

alter table public.products enable row level security;
create index if not exists products_merchant_id_idx on public.products (merchant_id);
create index if not exists products_category_id_idx on public.products (category_id);
create index if not exists products_subcategory_id_idx on public.products (subcategory_id);
create index if not exists products_tax_class_id_idx on public.products (tax_class_id);
create index if not exists products_supplier_id_idx on public.products (supplier_id);


-- 5. The child sets. Each references (product_id, merchant_id), so a child row cannot belong to a
-- product of another merchant, and carries merchant_id itself so its policy is the same one-line shape
-- as every other business table rather than a join back to products.

create table if not exists public.product_rate_tiers (
  id uuid primary key default gen_random_uuid(),
  product_id uuid not null,
  merchant_id uuid not null,
  position smallint not null default 0,
  period public.rate_period not null,
  price numeric(12, 2) not null,
  note text,

  constraint product_rate_tiers_product_fk foreign key (product_id, merchant_id)
    references public.products (id, merchant_id) on delete cascade,
  constraint product_rate_tiers_price_non_negative check (price >= 0),
  constraint product_rate_tiers_note_length check (note is null or length(note) <= 80)
);

alter table public.product_rate_tiers enable row level security;
create index if not exists product_rate_tiers_product_id_idx on public.product_rate_tiers (product_id, merchant_id);
create index if not exists product_rate_tiers_merchant_id_idx on public.product_rate_tiers (merchant_id);

create table if not exists public.product_operating_hours (
  id uuid primary key default gen_random_uuid(),
  product_id uuid not null,
  merchant_id uuid not null,
  -- 0 = Sunday, matching Date.getDay() on the client.
  weekday smallint not null,
  opens time not null,
  closes time not null,

  constraint product_operating_hours_product_fk foreign key (product_id, merchant_id)
    references public.products (id, merchant_id) on delete cascade,
  constraint product_operating_hours_weekday_range check (weekday between 0 and 6),
  constraint product_operating_hours_order check (opens < closes),
  constraint product_operating_hours_one_per_day unique (product_id, weekday)
);

alter table public.product_operating_hours enable row level security;
create index if not exists product_operating_hours_merchant_id_idx on public.product_operating_hours (merchant_id);

create table if not exists public.product_variant_attributes (
  id uuid primary key default gen_random_uuid(),
  product_id uuid not null,
  merchant_id uuid not null,
  position smallint not null default 0,
  name text not null,
  "values" text[] not null,

  constraint product_variant_attributes_product_fk foreign key (product_id, merchant_id)
    references public.products (id, merchant_id) on delete cascade,
  constraint product_variant_attributes_name_length check (length(btrim(name)) between 1 and 40),
  constraint product_variant_attributes_has_values check (cardinality("values") >= 1)
);

alter table public.product_variant_attributes enable row level security;
create index if not exists product_variant_attributes_product_id_idx on public.product_variant_attributes (product_id, merchant_id);
create index if not exists product_variant_attributes_merchant_id_idx on public.product_variant_attributes (merchant_id);

-- One row per attribute combination. qty_on_hand and barcode per variant were chosen by the human on
-- top of the spec's SKU and price delta.
create table if not exists public.product_variants (
  id uuid primary key default gen_random_uuid(),
  product_id uuid not null,
  merchant_id uuid not null,
  position smallint not null default 0,
  label text not null,
  options text[] not null,
  sku text,
  barcode text,
  price_delta numeric(12, 2) not null default 0,
  qty_on_hand numeric(12, 3),

  constraint product_variants_product_fk foreign key (product_id, merchant_id)
    references public.products (id, merchant_id) on delete cascade,
  constraint product_variants_label_unique unique (product_id, label),
  constraint product_variants_code_length check (
    (sku is null or length(sku) between 1 and 64) and (barcode is null or length(barcode) between 1 and 64)
  ),
  constraint product_variants_qty_non_negative check (coalesce(qty_on_hand, 0) >= 0)
);

alter table public.product_variants enable row level security;
create index if not exists product_variants_merchant_id_idx on public.product_variants (merchant_id);

-- The bill of materials: product_id is the bundle, component_id the product it contains.
create table if not exists public.product_components (
  id uuid primary key default gen_random_uuid(),
  product_id uuid not null,
  merchant_id uuid not null,
  position smallint not null default 0,
  component_id uuid not null,
  qty numeric(12, 3) not null,
  unit public.measure_unit,

  constraint product_components_product_fk foreign key (product_id, merchant_id)
    references public.products (id, merchant_id) on delete cascade,
  -- NO ACTION, not cascade: deleting a product that is inside a bundle fails (23503) instead of
  -- silently emptying the bundle. The client turns that into "used in a bundle" copy.
  constraint product_components_component_fk foreign key (component_id, merchant_id)
    references public.products (id, merchant_id),
  constraint product_components_not_self check (component_id <> product_id),
  constraint product_components_once unique (product_id, component_id),
  constraint product_components_qty_positive check (qty > 0)
);

alter table public.product_components enable row level security;
create index if not exists product_components_component_id_idx on public.product_components (component_id, merchant_id);
create index if not exists product_components_merchant_id_idx on public.product_components (merchant_id);

create table if not exists public.product_custom_fields (
  id uuid primary key default gen_random_uuid(),
  product_id uuid not null,
  merchant_id uuid not null,
  position smallint not null default 0,
  label text not null,
  kind public.custom_field_kind not null default 'text',
  value text,

  constraint product_custom_fields_product_fk foreign key (product_id, merchant_id)
    references public.products (id, merchant_id) on delete cascade,
  constraint product_custom_fields_label_length check (length(btrim(label)) between 1 and 40),
  constraint product_custom_fields_value_length check (value is null or length(value) <= 500)
);

alter table public.product_custom_fields enable row level security;
create index if not exists product_custom_fields_product_id_idx on public.product_custom_fields (product_id, merchant_id);
create index if not exists product_custom_fields_merchant_id_idx on public.product_custom_fields (merchant_id);


-- 6. Policies. The same four on every table above, keyed on membership of the row's merchant
-- (docs/tenancy.md §3). Written as a loop because ten tables of forty hand-copied statements is where a
-- missing `with check` hides.
--
-- Scoped `to authenticated`; the function call wrapped in a select so the planner runs it once per
-- statement as an InitPlan; update carries both `using` and `with check`, so a row cannot be moved to
-- another merchant (CLAUDE.md §6.3).
do $$
declare
  t text;
begin
  foreach t in array array[
    'product_categories', 'tax_classes', 'suppliers', 'products',
    'product_rate_tiers', 'product_operating_hours', 'product_variant_attributes',
    'product_variants', 'product_components', 'product_custom_fields'
  ]
  loop
    execute format('drop policy if exists %I on public.%I', t || '_select_own_merchant', t);
    execute format(
      'create policy %I on public.%I for select to authenticated
         using (merchant_id in (select private.current_merchant_ids()))',
      t || '_select_own_merchant', t
    );

    execute format('drop policy if exists %I on public.%I', t || '_insert_own_merchant', t);
    execute format(
      'create policy %I on public.%I for insert to authenticated
         with check (merchant_id in (select private.current_merchant_ids()))',
      t || '_insert_own_merchant', t
    );

    execute format('drop policy if exists %I on public.%I', t || '_update_own_merchant', t);
    execute format(
      'create policy %I on public.%I for update to authenticated
         using (merchant_id in (select private.current_merchant_ids()))
         with check (merchant_id in (select private.current_merchant_ids()))',
      t || '_update_own_merchant', t
    );

    execute format('drop policy if exists %I on public.%I', t || '_delete_own_merchant', t);
    execute format(
      'create policy %I on public.%I for delete to authenticated
         using (merchant_id in (select private.current_merchant_ids()))',
      t || '_delete_own_merchant', t
    );
  end loop;
end
$$;


-- 7. The circular-bundle guard. A check constraint can see only its own row, so "A contains B contains
-- A" needs a walk: from the new component, follow what it contains, and fail if the walk reaches the
-- bundle being written. `union` (not `union all`) is what stops the walk on data that is already cyclic.
--
-- Security invoker: RLS already limits the walk to the caller's merchant, and the composite foreign keys
-- mean a cycle cannot cross merchants anyway. Execute revoked like every function in `private` —
-- Postgres checks a trigger function's EXECUTE when the trigger is created, not when it fires.
create or replace function private.assert_no_bundle_cycle()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if exists (
    with recursive reach (id) as (
      select new.component_id
      union
      select pc.component_id
      from public.product_components pc
      join reach r on pc.product_id = r.id
    )
    select 1 from reach where reach.id = new.product_id
  ) then
    -- The message is the stable part the client matches on; never shown to the user.
    raise exception 'product_components_cycle'
      using errcode = '23514', detail = 'A bundle cannot contain itself, directly or through another bundle.';
  end if;
  return new;
end;
$$;

revoke execute on function private.assert_no_bundle_cycle() from public, anon, authenticated, service_role;

drop trigger if exists product_components_no_cycle on public.product_components;
create trigger product_components_no_cycle
  before insert or update of product_id, component_id on public.product_components
  for each row execute function private.assert_no_bundle_cycle();


-- 8. save_product: the whole form in one transaction.
--
-- A product save touches up to seven tables. Written from the client as seven requests, a dropped
-- connection halfway leaves a product with half its variants; as one function call it lands whole or
-- not at all.
--
-- Security INVOKER, so none of CLAUDE.md §6.2's escalation applies: every statement inside runs as the
-- caller, and the policies above gate each one exactly as they would a direct request. It is in
-- `public` because it is meant to be called; anon is revoked because there is nothing for anon to save.
--
-- ponytail: the child sets are deleted and reinserted, which gives variants new ids on every save. Fine
-- while nothing references a variant; switch to keyed upserts when orders do.
create or replace function public.save_product(payload jsonb)
returns uuid
language plpgsql
security invoker
set search_path = ''
as $$
declare
  p public.products;
  v_id uuid;
  v_merchant uuid;
begin
  p := jsonb_populate_record(null::public.products, payload -> 'product');

  if p.id is null then
    insert into public.products (
      merchant_id, type, name, category_id, subcategory_id, sku, barcode, description, tags, status,
      sold_directly, selling_price, cost_price, pricing_unit, tax_class_id, discountable,
      deposit_amount, late_fee_per_hour, cancellation_fee, extra_unit_fee,
      uom, track_inventory, qty_on_hand, reorder_threshold, reorder_qty, max_stock, storage_location,
      supplier_id, supplier_item_code, lead_time_days, batch_tracking, perishable, shelf_life_days,
      expiry_date, expiry_alert_days, purchase_unit, usage_unit, conversion_factor,
      total_units, capacity_per_unit, duration_mode, default_start_time, default_end_time,
      min_duration, min_duration_unit, max_duration, max_duration_unit, buffer_minutes,
      advance_window_days, blackout_dates, overbooking_allowed,
      has_variants, is_composite, internal_notes
    ) values (
      p.merchant_id, p.type, p.name, p.category_id, p.subcategory_id, p.sku, p.barcode, p.description,
      coalesce(p.tags, '{}'), coalesce(p.status, 'draft'),
      coalesce(p.sold_directly, true), p.selling_price, p.cost_price, p.pricing_unit, p.tax_class_id,
      coalesce(p.discountable, true),
      p.deposit_amount, p.late_fee_per_hour, p.cancellation_fee, p.extra_unit_fee,
      p.uom, coalesce(p.track_inventory, true), p.qty_on_hand, p.reorder_threshold, p.reorder_qty,
      p.max_stock, p.storage_location,
      p.supplier_id, p.supplier_item_code, p.lead_time_days, coalesce(p.batch_tracking, false),
      coalesce(p.perishable, false), p.shelf_life_days,
      p.expiry_date, p.expiry_alert_days, p.purchase_unit, p.usage_unit, p.conversion_factor,
      p.total_units, p.capacity_per_unit, p.duration_mode, p.default_start_time, p.default_end_time,
      p.min_duration, p.min_duration_unit, p.max_duration, p.max_duration_unit, p.buffer_minutes,
      p.advance_window_days, coalesce(p.blackout_dates, '{}'), coalesce(p.overbooking_allowed, false),
      coalesce(p.has_variants, false), coalesce(p.is_composite, false), p.internal_notes
    )
    returning id, merchant_id into v_id, v_merchant;
  else
    -- merchant_id is deliberately not in the SET list: a product does not move between merchants, and
    -- its child rows' composite keys would refuse it anyway.
    update public.products set
      type = p.type, name = p.name, category_id = p.category_id, subcategory_id = p.subcategory_id,
      sku = p.sku, barcode = p.barcode, description = p.description, tags = coalesce(p.tags, '{}'),
      status = coalesce(p.status, 'draft'), sold_directly = coalesce(p.sold_directly, true),
      selling_price = p.selling_price, cost_price = p.cost_price, pricing_unit = p.pricing_unit,
      tax_class_id = p.tax_class_id, discountable = coalesce(p.discountable, true),
      deposit_amount = p.deposit_amount, late_fee_per_hour = p.late_fee_per_hour,
      cancellation_fee = p.cancellation_fee, extra_unit_fee = p.extra_unit_fee,
      uom = p.uom, track_inventory = coalesce(p.track_inventory, true), qty_on_hand = p.qty_on_hand,
      reorder_threshold = p.reorder_threshold, reorder_qty = p.reorder_qty, max_stock = p.max_stock,
      storage_location = p.storage_location, supplier_id = p.supplier_id,
      supplier_item_code = p.supplier_item_code, lead_time_days = p.lead_time_days,
      batch_tracking = coalesce(p.batch_tracking, false), perishable = coalesce(p.perishable, false),
      shelf_life_days = p.shelf_life_days, expiry_date = p.expiry_date,
      expiry_alert_days = p.expiry_alert_days, purchase_unit = p.purchase_unit,
      usage_unit = p.usage_unit, conversion_factor = p.conversion_factor,
      total_units = p.total_units, capacity_per_unit = p.capacity_per_unit,
      duration_mode = p.duration_mode, default_start_time = p.default_start_time,
      default_end_time = p.default_end_time, min_duration = p.min_duration,
      min_duration_unit = p.min_duration_unit, max_duration = p.max_duration,
      max_duration_unit = p.max_duration_unit, buffer_minutes = p.buffer_minutes,
      advance_window_days = p.advance_window_days, blackout_dates = coalesce(p.blackout_dates, '{}'),
      overbooking_allowed = coalesce(p.overbooking_allowed, false),
      has_variants = coalesce(p.has_variants, false), is_composite = coalesce(p.is_composite, false),
      internal_notes = p.internal_notes, updated_at = now()
    where id = p.id
    returning id, merchant_id into v_id, v_merchant;

    -- RLS filters an UPDATE rather than refusing it, so another merchant's id updates zero rows.
    if v_id is null then
      raise exception 'product_not_found' using errcode = 'P0002';
    end if;
  end if;

  delete from public.product_rate_tiers where product_id = v_id;
  delete from public.product_operating_hours where product_id = v_id;
  delete from public.product_variant_attributes where product_id = v_id;
  delete from public.product_variants where product_id = v_id;
  delete from public.product_components where product_id = v_id;
  delete from public.product_custom_fields where product_id = v_id;

  insert into public.product_rate_tiers (product_id, merchant_id, position, period, price, note)
  select v_id, v_merchant, (e.idx - 1)::smallint, x.period, x.price, x.note
  from jsonb_array_elements(coalesce(payload -> 'rate_tiers', '[]')) with ordinality as e (value, idx)
  cross join lateral jsonb_populate_record(null::public.product_rate_tiers, e.value) as x;

  insert into public.product_operating_hours (product_id, merchant_id, weekday, opens, closes)
  select v_id, v_merchant, x.weekday, x.opens, x.closes
  from jsonb_array_elements(coalesce(payload -> 'operating_hours', '[]')) as e (value)
  cross join lateral jsonb_populate_record(null::public.product_operating_hours, e.value) as x;

  insert into public.product_variant_attributes (product_id, merchant_id, position, name, "values")
  select v_id, v_merchant, (e.idx - 1)::smallint, x.name, x."values"
  from jsonb_array_elements(coalesce(payload -> 'variant_attributes', '[]')) with ordinality as e (value, idx)
  cross join lateral jsonb_populate_record(null::public.product_variant_attributes, e.value) as x;

  insert into public.product_variants (
    product_id, merchant_id, position, label, options, sku, barcode, price_delta, qty_on_hand
  )
  select v_id, v_merchant, (e.idx - 1)::smallint, x.label, x.options, x.sku, x.barcode,
    coalesce(x.price_delta, 0), x.qty_on_hand
  from jsonb_array_elements(coalesce(payload -> 'variants', '[]')) with ordinality as e (value, idx)
  cross join lateral jsonb_populate_record(null::public.product_variants, e.value) as x;

  insert into public.product_components (product_id, merchant_id, position, component_id, qty, unit)
  select v_id, v_merchant, (e.idx - 1)::smallint, x.component_id, x.qty, x.unit
  from jsonb_array_elements(coalesce(payload -> 'components', '[]')) with ordinality as e (value, idx)
  cross join lateral jsonb_populate_record(null::public.product_components, e.value) as x;

  insert into public.product_custom_fields (product_id, merchant_id, position, label, kind, value)
  select v_id, v_merchant, (e.idx - 1)::smallint, x.label, coalesce(x.kind, 'text'), x.value
  from jsonb_array_elements(coalesce(payload -> 'custom_fields', '[]')) with ordinality as e (value, idx)
  cross join lateral jsonb_populate_record(null::public.product_custom_fields, e.value) as x;

  return v_id;
end;
$$;

revoke execute on function public.save_product(jsonb) from public, anon, authenticated, service_role;
grant execute on function public.save_product(jsonb) to authenticated;


-- ===== 20260917183630_resource_scopes.sql =====

-- The Resources split. The merchant shell's Products destination becomes three: Products (flat
-- services), Rentables (rental assets and bookable services) and Inventory (stock and consumables).
-- Each screen owns its own categories, and a product belongs to exactly one screen, decided by its
-- type. See .claude/context/System-History/version-13.1.md.
--
-- 1. category_scope, and a scope on every category.
-- 2. products.scope, generated from the type, so the category foreign keys can refuse a product
--    pointing at another screen's category.
-- 3. save_product stops changing a product's type: the screen it was created on decides it, and a
--    type change would move the product to another screen behind the merchant's back.


-- 1. Category scope. Three values, one per screen.
do $$
begin
  if to_regtype('public.category_scope') is null then
    create type public.category_scope as enum ('products', 'rentables', 'inventory');
  end if;
end
$$;

alter table public.product_categories add column if not exists scope public.category_scope;

-- The mapping this whole migration turns on: type -> screen. Written out at each use rather than as a
-- function: a function in `public` is a /rest/v1/rpc URL (CLAUDE.md §6.1), and the generated column
-- below cannot call one anyway.
--
-- A category serving two screens has no single right answer, so the migration stops rather than
-- guessing. Verified clean on the hosted project on 2026-09-18: every used category serves one scope.
do $$
begin
  if exists (
    select 1
    from public.products p
    join public.product_categories c on c.id in (p.category_id, p.subcategory_id)
    group by coalesce(c.parent_id, c.id)
    having count(distinct (p.type in ('rental', 'bookable'))) > 1
        or count(distinct (p.type = 'stock')) > 1
  ) then
    raise exception 'category_used_across_scopes'
      using detail = 'A category is used by two Resources screens; split it before applying.';
  end if;
end
$$;

-- Top-level categories take the scope of the products using them or their subcategories;
-- subcategories take their parent's; anything unused lands in Products.
update public.product_categories c
set scope = u.scope
from (
  select distinct coalesce(cat.parent_id, cat.id) as top_id,
    (case p.type
      when 'stock' then 'inventory'
      when 'rental' then 'rentables'
      when 'bookable' then 'rentables'
      else 'products'
    end)::public.category_scope as scope
  from public.products p
  join public.product_categories cat on cat.id in (p.category_id, p.subcategory_id)
) u
where c.id = u.top_id and c.scope is null;

update public.product_categories c set scope = coalesce(parent.scope, 'products')
from public.product_categories parent
where c.parent_id = parent.id and c.scope is null;

update public.product_categories set scope = 'products' where scope is null;

-- No default: a category written without a scope is a client bug, and should fail as one.
alter table public.product_categories alter column scope set not null;


-- 2. Product scope and the keys that use it. Dropped first and re-added, so the file re-runs.
--
-- A trigger, not a generated column: Postgres requires a generation expression to be immutable, and
-- every route from a literal to an enum value goes through enum_in, which is only stable
-- (`42P17: generation expression is not immutable`). The trigger writes the column on every insert
-- and on every change of type, so the client cannot set it to something else — the same guarantee,
-- one object further out.
alter table public.products add column if not exists scope public.category_scope;

create or replace function private.set_product_scope()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.scope := case new.type
    when 'stock' then 'inventory'
    when 'rental' then 'rentables'
    when 'bookable' then 'rentables'
    else 'products'
  end::public.category_scope;
  return new;
end;
$$;

revoke execute on function private.set_product_scope() from public, anon, authenticated, service_role;

drop trigger if exists set_product_scope on public.products;
create trigger set_product_scope
  before insert or update of type on public.products
  for each row execute function private.set_product_scope();

update public.products set scope = case type
  when 'stock' then 'inventory'
  when 'rental' then 'rentables'
  when 'bookable' then 'rentables'
  else 'products'
end::public.category_scope
where scope is null;

alter table public.products alter column scope set not null;

alter table public.products drop constraint if exists products_category_fk;
alter table public.products drop constraint if exists products_subcategory_fk;
alter table public.product_categories drop constraint if exists product_categories_parent_fk;
alter table public.product_categories drop constraint if exists product_categories_name_unique;
alter table public.product_categories drop constraint if exists product_categories_id_merchant_scope;

alter table public.product_categories
  add constraint product_categories_id_merchant_scope unique (id, merchant_id, scope);

-- A subcategory lives in its parent's scope.
alter table public.product_categories
  add constraint product_categories_parent_fk foreign key (parent_id, merchant_id, scope)
    references public.product_categories (id, merchant_id, scope) on delete cascade;

-- The same name may exist once per screen: "Drinks" in Products and "Drinks" in Inventory are two lists.
alter table public.product_categories
  add constraint product_categories_name_unique unique nulls not distinct (merchant_id, scope, parent_id, name);

-- NO ACTION, like the keys they replace. This is what stops a Rentables product pointing at an
-- Inventory category: the scope is derived from the type, so the pair simply has no row to reference.
alter table public.products
  add constraint products_category_fk foreign key (category_id, merchant_id, scope)
    references public.product_categories (id, merchant_id, scope);
alter table public.products
  add constraint products_subcategory_fk foreign key (subcategory_id, merchant_id, scope)
    references public.product_categories (id, merchant_id, scope);


-- 3. save_product, the writer for all three screens.
--
-- Changed from 20260914092147_products.sql in one place: `type` leaves the update list. A product is
-- created on one screen and stays there; changing its type would move it to another screen's list and
-- silently orphan its category, which the keys above would refuse anyway.
--
-- Everything else — security invoker, the child-set rewrite, the ponytail note on variant ids — is as
-- that file explains. Stock columns stay here: Inventory owns its products outright, so there is one
-- writer and nothing to race with.
create or replace function public.save_product(payload jsonb)
returns uuid
language plpgsql
security invoker
set search_path = ''
as $$
declare
  p public.products;
  v_id uuid;
  v_merchant uuid;
begin
  p := jsonb_populate_record(null::public.products, payload -> 'product');

  if p.id is null then
    insert into public.products (
      merchant_id, type, name, category_id, subcategory_id, sku, barcode, description, tags, status,
      sold_directly, selling_price, cost_price, pricing_unit, tax_class_id, discountable,
      deposit_amount, late_fee_per_hour, cancellation_fee, extra_unit_fee,
      uom, track_inventory, qty_on_hand, reorder_threshold, reorder_qty, max_stock, storage_location,
      supplier_id, supplier_item_code, lead_time_days, batch_tracking, perishable, shelf_life_days,
      expiry_date, expiry_alert_days, purchase_unit, usage_unit, conversion_factor,
      total_units, capacity_per_unit, duration_mode, default_start_time, default_end_time,
      min_duration, min_duration_unit, max_duration, max_duration_unit, buffer_minutes,
      advance_window_days, blackout_dates, overbooking_allowed,
      has_variants, is_composite, internal_notes
    ) values (
      p.merchant_id, p.type, p.name, p.category_id, p.subcategory_id, p.sku, p.barcode, p.description,
      coalesce(p.tags, '{}'), coalesce(p.status, 'draft'),
      coalesce(p.sold_directly, true), p.selling_price, p.cost_price, p.pricing_unit, p.tax_class_id,
      coalesce(p.discountable, true),
      p.deposit_amount, p.late_fee_per_hour, p.cancellation_fee, p.extra_unit_fee,
      p.uom, coalesce(p.track_inventory, true), p.qty_on_hand, p.reorder_threshold, p.reorder_qty,
      p.max_stock, p.storage_location,
      p.supplier_id, p.supplier_item_code, p.lead_time_days, coalesce(p.batch_tracking, false),
      coalesce(p.perishable, false), p.shelf_life_days,
      p.expiry_date, p.expiry_alert_days, p.purchase_unit, p.usage_unit, p.conversion_factor,
      p.total_units, p.capacity_per_unit, p.duration_mode, p.default_start_time, p.default_end_time,
      p.min_duration, p.min_duration_unit, p.max_duration, p.max_duration_unit, p.buffer_minutes,
      p.advance_window_days, coalesce(p.blackout_dates, '{}'), coalesce(p.overbooking_allowed, false),
      coalesce(p.has_variants, false), coalesce(p.is_composite, false), p.internal_notes
    )
    returning id, merchant_id into v_id, v_merchant;
  else
    -- merchant_id and type are deliberately not in the SET list: a product does not move between
    -- merchants, and it does not move between Resources screens.
    update public.products set
      name = p.name, category_id = p.category_id, subcategory_id = p.subcategory_id,
      sku = p.sku, barcode = p.barcode, description = p.description, tags = coalesce(p.tags, '{}'),
      status = coalesce(p.status, 'draft'), sold_directly = coalesce(p.sold_directly, true),
      selling_price = p.selling_price, cost_price = p.cost_price, pricing_unit = p.pricing_unit,
      tax_class_id = p.tax_class_id, discountable = coalesce(p.discountable, true),
      deposit_amount = p.deposit_amount, late_fee_per_hour = p.late_fee_per_hour,
      cancellation_fee = p.cancellation_fee, extra_unit_fee = p.extra_unit_fee,
      uom = p.uom, track_inventory = coalesce(p.track_inventory, true), qty_on_hand = p.qty_on_hand,
      reorder_threshold = p.reorder_threshold, reorder_qty = p.reorder_qty, max_stock = p.max_stock,
      storage_location = p.storage_location, supplier_id = p.supplier_id,
      supplier_item_code = p.supplier_item_code, lead_time_days = p.lead_time_days,
      batch_tracking = coalesce(p.batch_tracking, false), perishable = coalesce(p.perishable, false),
      shelf_life_days = p.shelf_life_days, expiry_date = p.expiry_date,
      expiry_alert_days = p.expiry_alert_days, purchase_unit = p.purchase_unit,
      usage_unit = p.usage_unit, conversion_factor = p.conversion_factor,
      total_units = p.total_units, capacity_per_unit = p.capacity_per_unit,
      duration_mode = p.duration_mode, default_start_time = p.default_start_time,
      default_end_time = p.default_end_time, min_duration = p.min_duration,
      min_duration_unit = p.min_duration_unit, max_duration = p.max_duration,
      max_duration_unit = p.max_duration_unit, buffer_minutes = p.buffer_minutes,
      advance_window_days = p.advance_window_days, blackout_dates = coalesce(p.blackout_dates, '{}'),
      overbooking_allowed = coalesce(p.overbooking_allowed, false),
      has_variants = coalesce(p.has_variants, false), is_composite = coalesce(p.is_composite, false),
      internal_notes = p.internal_notes, updated_at = now()
    where id = p.id
    returning id, merchant_id into v_id, v_merchant;

    -- RLS filters an UPDATE rather than refusing it, so another merchant's id updates zero rows.
    if v_id is null then
      raise exception 'product_not_found' using errcode = 'P0002';
    end if;
  end if;

  delete from public.product_rate_tiers where product_id = v_id;
  delete from public.product_operating_hours where product_id = v_id;
  delete from public.product_variant_attributes where product_id = v_id;
  delete from public.product_variants where product_id = v_id;
  delete from public.product_components where product_id = v_id;
  delete from public.product_custom_fields where product_id = v_id;

  insert into public.product_rate_tiers (product_id, merchant_id, position, period, price, note)
  select v_id, v_merchant, (e.idx - 1)::smallint, x.period, x.price, x.note
  from jsonb_array_elements(coalesce(payload -> 'rate_tiers', '[]')) with ordinality as e (value, idx)
  cross join lateral jsonb_populate_record(null::public.product_rate_tiers, e.value) as x;

  insert into public.product_operating_hours (product_id, merchant_id, weekday, opens, closes)
  select v_id, v_merchant, x.weekday, x.opens, x.closes
  from jsonb_array_elements(coalesce(payload -> 'operating_hours', '[]')) as e (value)
  cross join lateral jsonb_populate_record(null::public.product_operating_hours, e.value) as x;

  insert into public.product_variant_attributes (product_id, merchant_id, position, name, "values")
  select v_id, v_merchant, (e.idx - 1)::smallint, x.name, x."values"
  from jsonb_array_elements(coalesce(payload -> 'variant_attributes', '[]')) with ordinality as e (value, idx)
  cross join lateral jsonb_populate_record(null::public.product_variant_attributes, e.value) as x;

  insert into public.product_variants (
    product_id, merchant_id, position, label, options, sku, barcode, price_delta, qty_on_hand
  )
  select v_id, v_merchant, (e.idx - 1)::smallint, x.label, x.options, x.sku, x.barcode,
    coalesce(x.price_delta, 0), x.qty_on_hand
  from jsonb_array_elements(coalesce(payload -> 'variants', '[]')) with ordinality as e (value, idx)
  cross join lateral jsonb_populate_record(null::public.product_variants, e.value) as x;

  insert into public.product_components (product_id, merchant_id, position, component_id, qty, unit)
  select v_id, v_merchant, (e.idx - 1)::smallint, x.component_id, x.qty, x.unit
  from jsonb_array_elements(coalesce(payload -> 'components', '[]')) with ordinality as e (value, idx)
  cross join lateral jsonb_populate_record(null::public.product_components, e.value) as x;

  insert into public.product_custom_fields (product_id, merchant_id, position, label, kind, value)
  select v_id, v_merchant, (e.idx - 1)::smallint, x.label, coalesce(x.kind, 'text'), x.value
  from jsonb_array_elements(coalesce(payload -> 'custom_fields', '[]')) with ordinality as e (value, idx)
  cross join lateral jsonb_populate_record(null::public.product_custom_fields, e.value) as x;

  return v_id;
end;
$$;

revoke execute on function public.save_product(jsonb) from public, anon, authenticated, service_role;
grant execute on function public.save_product(jsonb) to authenticated;


-- ===== 20260928100000_suppliers_extend.sql =====

-- Suppliers, extended for the Stock screen (.claude/inventory-stock/design.md §2).
--
-- 1. private.merchant_counters and the code issuer every generated code goes through: SUP here, SKU in
--    20260928100100_stock_items.sql, RC / LOT / CS / PK in 20260928100200_stock_receipts.sql.
-- 2. supplier_types, the per-merchant lookup the supplier form manages inline.
-- 3. suppliers: contact becomes contact_person, and the Profile / Terms / Extra columns arrive.
--
-- Re-runnable, like the rest of supabase/migrations.

create schema if not exists private;


-- 1. Codes.
--
-- A counter row per (merchant, kind) rather than a Postgres sequence per merchant: a sequence is a
-- schema object, and making one per merchant at signup would be DDL from application code. The upsert
-- takes a row lock, so two concurrent saves for one merchant get consecutive numbers, never the same
-- one. A rolled-back save rolls its number back with it; a committed one is never issued again, which is
-- what "never reused" asks of a SKU or a lot number.
create table if not exists private.merchant_counters (
  merchant_id uuid not null references public.merchants (id) on delete cascade,
  kind text not null,
  next bigint not null,
  primary key (merchant_id, kind)
);

-- No policies: only functions owned by the table owner write it. RLS is on anyway (CLAUDE.md §6.1), and
-- the grants below keep the USAGE authenticated holds on `private` from reaching it.
alter table private.merchant_counters enable row level security;
revoke all on private.merchant_counters from public, anon, authenticated;

create or replace function private.next_number(p_merchant uuid, p_kind text)
returns bigint
language sql
set search_path = ''
as $$
  insert into private.merchant_counters as c (merchant_id, kind, next)
  values (p_merchant, p_kind, 2)
  on conflict (merchant_id, kind) do update set next = c.next + 1
  returning c.next - 1;
$$;

-- The next free code of a kind: the prefix, then the counter zero-padded to p_width (and longer once it
-- outgrows it). Skips a value already present in p_table.p_column, because a merchant may type a code of
-- their own that a later generated one would otherwise collide with.
create or replace function private.issue_code(
  p_merchant uuid, p_kind text, p_prefix text, p_width integer, p_table regclass, p_column text
)
returns text
language plpgsql
set search_path = ''
as $$
declare
  v_number text;
  v_code text;
  v_taken boolean;
begin
  loop
    v_number := private.next_number(p_merchant, p_kind)::text;
    v_code := p_prefix || repeat('0', greatest(p_width - length(v_number), 0)) || v_number;
    execute format('select exists (select 1 from %s where merchant_id = $1 and %I = $2)', p_table, p_column)
      into v_taken using p_merchant, v_code;
    exit when not v_taken;
  end loop;
  return v_code;
end;
$$;

-- The membership check the stock functions open with (CLAUDE.md §6.2 item 3): current_merchant_ids()
-- answers for (select auth.uid()), so a caller can only ever act on their own merchant's rows.
create or replace function private.assert_member(p_merchant uuid)
returns void
language plpgsql
stable
set search_path = ''
as $$
begin
  if not exists (select 1 from private.current_merchant_ids() as m (id) where m.id = p_merchant) then
    raise exception 'not_a_member' using errcode = '42501';
  end if;
end;
$$;

-- Fills a blank code column on insert. Arguments: counter kind, prefix, width, column name.
--
-- Security definer because the client inserts suppliers and products directly, and the counters are
-- out of its reach. The membership check keeps a caller from advancing another merchant's counter; no
-- JWT means a migration or the SQL Editor, both of which already run as the owner.
create or replace function private.assign_code()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if (select auth.uid()) is not null then
    perform private.assert_member(new.merchant_id);
  end if;

  new := jsonb_populate_record(new, jsonb_build_object(
    tg_argv[3],
    private.issue_code(new.merchant_id, tg_argv[0], tg_argv[1], tg_argv[2]::integer, tg_relid::regclass, tg_argv[3])
  ));
  return new;
end;
$$;

revoke execute on function private.next_number(uuid, text) from public, anon, authenticated, service_role;
revoke execute on function private.issue_code(uuid, text, text, integer, regclass, text)
  from public, anon, authenticated, service_role;
revoke execute on function private.assert_member(uuid) from public, anon, authenticated, service_role;
revoke execute on function private.assign_code() from public, anon, authenticated, service_role;


-- 2. Supplier types. Same lookup shape as tax_classes: unique (id, merchant_id) so a supplier's key can
-- only reach a type of its own merchant.
create table if not exists public.supplier_types (
  id uuid primary key default gen_random_uuid(),
  merchant_id uuid not null references public.merchants (id) on delete cascade,
  name text not null,
  created_at timestamptz not null default now(),

  constraint supplier_types_id_merchant unique (id, merchant_id),
  constraint supplier_types_name_length check (length(btrim(name)) between 1 and 40),
  constraint supplier_types_name_unique unique (merchant_id, name)
);

alter table public.supplier_types enable row level security;


-- 3. Suppliers.
--
-- contact is renamed rather than dropped, so what merchants typed there survives as the contact person.
do $$
begin
  if exists (
    select 1 from information_schema.columns
    where table_schema = 'public' and table_name = 'suppliers' and column_name = 'contact'
  ) then
    alter table public.suppliers rename column contact to contact_person;
  end if;
  if exists (select 1 from pg_constraint where conname = 'suppliers_contact_length') then
    alter table public.suppliers rename constraint suppliers_contact_length to suppliers_contact_person_length;
  end if;
end
$$;

alter table public.suppliers
  add column if not exists code text,
  add column if not exists phone text,
  add column if not exists email text,
  add column if not exists address text,
  add column if not exists payment_terms text,
  add column if not exists supplier_type_id uuid,
  add column if not exists lead_time_days integer,
  add column if not exists tin text,
  -- Inactive suppliers drop out of the receipt picker. A supplier with receipts can only be deactivated:
  -- stock_receipts' key to it refuses the delete.
  add column if not exists active boolean not null default true,
  add column if not exists notes text;

alter table public.suppliers drop constraint if exists suppliers_type_fk;
alter table public.suppliers drop constraint if exists suppliers_code_unique;
alter table public.suppliers drop constraint if exists suppliers_details_length;
alter table public.suppliers drop constraint if exists suppliers_lead_time_non_negative;

alter table public.suppliers
  add constraint suppliers_type_fk foreign key (supplier_type_id, merchant_id)
    references public.supplier_types (id, merchant_id) on delete set null (supplier_type_id);
alter table public.suppliers
  add constraint suppliers_code_unique unique (merchant_id, code);
-- TIN is text, not a number: Philippine TINs are written with dashes and a branch code.
alter table public.suppliers
  add constraint suppliers_details_length check (
    (code is null or length(btrim(code)) between 1 and 20)
    and (phone is null or length(phone) <= 32)
    and (email is null or length(email) <= 255)
    and (address is null or length(address) <= 255)
    and (payment_terms is null or length(payment_terms) <= 60)
    and (tin is null or length(tin) <= 20)
    and (notes is null or length(notes) <= 2000)
  );
alter table public.suppliers
  add constraint suppliers_lead_time_non_negative check (lead_time_days is null or lead_time_days >= 0);

create index if not exists suppliers_supplier_type_id_idx on public.suppliers (supplier_type_id);

drop trigger if exists suppliers_assign_code on public.suppliers;
create trigger suppliers_assign_code
  before insert or update of code on public.suppliers
  for each row when (new.code is null)
  execute function private.assign_code('supplier', 'SUP-', '4', 'code');

-- Existing suppliers get codes in the order they were created.
do $$
declare
  s record;
begin
  for s in select id, merchant_id from public.suppliers where code is null order by merchant_id, created_at, id loop
    update public.suppliers
    set code = private.issue_code(s.merchant_id, 'supplier', 'SUP-', 4, 'public.suppliers', 'code')
    where id = s.id;
  end loop;
end
$$;

-- Safe: the trigger fills every insert that leaves it blank.
alter table public.suppliers alter column code set not null;


-- 4. Policies on the new table, the same four as 20260914092147_products.sql §6.
do $$
declare
  t text := 'supplier_types';
begin
  execute format('drop policy if exists %I on public.%I', t || '_select_own_merchant', t);
  execute format(
    'create policy %I on public.%I for select to authenticated
       using (merchant_id in (select private.current_merchant_ids()))',
    t || '_select_own_merchant', t
  );

  execute format('drop policy if exists %I on public.%I', t || '_insert_own_merchant', t);
  execute format(
    'create policy %I on public.%I for insert to authenticated
       with check (merchant_id in (select private.current_merchant_ids()))',
    t || '_insert_own_merchant', t
  );

  execute format('drop policy if exists %I on public.%I', t || '_update_own_merchant', t);
  execute format(
    'create policy %I on public.%I for update to authenticated
       using (merchant_id in (select private.current_merchant_ids()))
       with check (merchant_id in (select private.current_merchant_ids()))',
    t || '_update_own_merchant', t
  );

  execute format('drop policy if exists %I on public.%I', t || '_delete_own_merchant', t);
  execute format(
    'create policy %I on public.%I for delete to authenticated
       using (merchant_id in (select private.current_merchant_ids()))',
    t || '_delete_own_merchant', t
  );
end
$$;


-- ===== 20260928100300_supplier_code_default.sql =====

-- A blank supplier code is generated.
--
-- suppliers.code is not null and filled by a trigger, but a column with no default is required in the
-- generated Insert type, so the app could not insert a supplier without typing a code. The default is
-- '' and the trigger now treats a blank code the same as a missing one: the SUP-#### it issues replaces
-- it before suppliers_details_length is checked. The same holds on update, so clearing a code in the
-- form issues a new one.

alter table public.suppliers alter column code set default '';

drop trigger if exists suppliers_assign_code on public.suppliers;
create trigger suppliers_assign_code
  before insert or update of code on public.suppliers
  for each row when (new.code is null or btrim(new.code) = '')
  execute function private.assign_code('supplier', 'SUP-', '4', 'code');


-- ===== 20260929100000_stock_items.sql =====

-- Inventory items (.claude/inventory-stock/instructions.txt, Inventory.html).
--
-- 1. stock_sell_by and stock_role.
-- 2. product_groups: the parent a variant hangs under. Each variant is its own stock row.
-- 3. The stock columns on products, the link from a Products-screen face to the item it sells, and
--    category made optional for drafts and stock items.
-- 4. A generated SKU for every stock item that is saved without one.
-- 5. product_groups' policies.
-- 6. Register faces: the draft Products-screen rows an item is sold through, kept in step by a trigger.
-- 7. save_stock_item: the Inventory form's writer.
--
-- The item is the master record (name, SKU, units, role, category). Price, tax and recipe live on its
-- faces, one per Sell By unit, because a pack and a tablet are priced apart. The physical stock — lots
-- and packs, with their lot numbers, serials and expiry — is 20260929100100_stock_ledger.sql.
--
-- Column reuse, rather than a second column meaning the same thing:
--   conversion_factor   base units per pack (1 when the item is sold by the pack only)
--   perishable          "has expiry": when true, every receipt line needs an expiry date
--   reorder_threshold   re-order point, in base units
--   internal_notes      the form's Notes

-- 1. Enums.
do $$
begin
  if to_regtype('public.stock_sell_by') is null then
    create type public.stock_sell_by as enum ('pack', 'base', 'both');
  end if;
  if to_regtype('public.stock_role') is null then
    create type public.stock_role as enum ('sellable', 'component', 'both');
  end if;
end
$$;


-- 2. Product groups.
create table if not exists public.product_groups (
  id uuid primary key default gen_random_uuid(),
  merchant_id uuid not null references public.merchants (id) on delete cascade,
  name text not null,
  created_at timestamptz not null default now(),

  constraint product_groups_id_merchant unique (id, merchant_id),
  constraint product_groups_name_length check (length(btrim(name)) between 1 and 120),
  constraint product_groups_name_unique unique (merchant_id, name)
);

alter table public.product_groups enable row level security;


-- 3. Stock columns.
alter table public.products
  add column if not exists pack_unit_name text,
  add column if not exists base_unit_name text,
  add column if not exists sell_by public.stock_sell_by,
  add column if not exists stock_role public.stock_role,
  add column if not exists group_id uuid,
  add column if not exists attributes text[] not null default '{}',
  -- Set on a Products-screen face; points at the stock item it sells.
  add column if not exists source_item_id uuid;

alter table public.products drop constraint if exists products_group_fk;
alter table public.products drop constraint if exists products_source_item_fk;
alter table public.products drop constraint if exists products_unit_names_length;
alter table public.products drop constraint if exists products_category_required;
alter table public.products drop constraint if exists products_stock_fields;

alter table public.products
  add constraint products_group_fk foreign key (group_id, merchant_id)
    references public.product_groups (id, merchant_id) on delete set null (group_id);
-- NO ACTION: a face's component row already refuses deleting the item while the face exists.
alter table public.products
  add constraint products_source_item_fk foreign key (source_item_id, merchant_id)
    references public.products (id, merchant_id);
-- 20 characters keeps a face's name, "<item> (<unit>)", inside products_name_length.
alter table public.products
  add constraint products_unit_names_length check (
    (pack_unit_name is null or length(btrim(pack_unit_name)) between 1 and 20)
    and (base_unit_name is null or length(btrim(base_unit_name)) between 1 and 20)
  );
-- A stock row from before this file is a component sold by the pack until someone says otherwise.
update public.products set sell_by = coalesce(sell_by, 'pack'), stock_role = coalesce(stock_role, 'component')
where type = 'stock' and (sell_by is null or stock_role is null);

-- A face is made with no category (the item's category belongs to Inventory, not to Products), and the
-- Inventory form marks Category optional. Everything else still needs one.
alter table public.products alter column category_id drop not null;
alter table public.products
  add constraint products_category_required check (category_id is not null or status = 'draft' or type = 'stock');

create index if not exists products_group_id_idx on public.products (group_id);
create index if not exists products_source_item_id_idx on public.products (source_item_id);


-- 4. SKUs. A stock item saved without one gets SKU-#####, unique per merchant and never reissued. A
-- blank SKU counts as none, so clearing it on the form issues a new one.
drop trigger if exists products_assign_sku on public.products;
create trigger products_assign_sku
  before insert or update of sku on public.products
  for each row when (new.type = 'stock' and (new.sku is null or btrim(new.sku) = ''))
  execute function private.assign_code('sku', 'SKU-', '5', 'sku');

-- Stock rows from before this file, oldest first. `set sku = null` fires the trigger above.
do $$
declare
  v_id uuid;
begin
  for v_id in
    select id from public.products where type = 'stock' and sku is null order by merchant_id, created_at, id
  loop
    update public.products set sku = null where id = v_id;
  end loop;
end
$$;

-- A stock item always has a SKU, and knows how it is sold and used. The trigger above fills the SKU
-- before this is checked.
alter table public.products
  add constraint products_stock_fields check (
    type <> 'stock' or (sku is not null and sell_by is not null and stock_role is not null)
  );


-- 5. Policies on product_groups, the same four as 20260914092147_products.sql §6.
do $$
declare
  t text := 'product_groups';
begin
  execute format('drop policy if exists %I on public.%I', t || '_select_own_merchant', t);
  execute format(
    'create policy %I on public.%I for select to authenticated
       using (merchant_id in (select private.current_merchant_ids()))',
    t || '_select_own_merchant', t
  );

  execute format('drop policy if exists %I on public.%I', t || '_insert_own_merchant', t);
  execute format(
    'create policy %I on public.%I for insert to authenticated
       with check (merchant_id in (select private.current_merchant_ids()))',
    t || '_insert_own_merchant', t
  );

  execute format('drop policy if exists %I on public.%I', t || '_update_own_merchant', t);
  execute format(
    'create policy %I on public.%I for update to authenticated
       using (merchant_id in (select private.current_merchant_ids()))
       with check (merchant_id in (select private.current_merchant_ids()))',
    t || '_update_own_merchant', t
  );

  execute format('drop policy if exists %I on public.%I', t || '_delete_own_merchant', t);
  execute format(
    'create policy %I on public.%I for delete to authenticated
       using (merchant_id in (select private.current_merchant_ids()))',
    t || '_delete_own_merchant', t
  );
end
$$;


-- 6. Register faces.
--
-- An item that is Sellable or Both is sold through one draft 'flat' product per Sell By unit: "<item>
-- (<pack unit>)" drawing one pack, and "<item> (<base unit>)" drawing one base unit, each through a
-- single product_components row. The draft lands in Products with no price; staff price it and publish
-- it before the Register can sell it. A face's name, price and category are staff's once made, so
-- nothing here writes them again.
--
-- A unit no longer wanted — Component, a narrower Sell By, an archived item:
--   still a draft, used by nothing   deleted; wanting the unit again makes a fresh draft
--   published (active or inactive)   archived, keeping its price and category; wanting it restores it
--                                    as a draft, so staff re-publish it on purpose
--   a draft another recipe uses      left alone
-- A draft is never archived: products_price_when_sold and products_category_required only let a
-- product without price or category exist as a draft.
--
-- Security invoker: RLS gates every statement. Callable directly by "Add from Inventory" (a face deleted
-- by hand comes back), and by the trigger below whenever role, Sell By or status changes.
create or replace function public.ensure_register_faces(p_item uuid)
returns void
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_item public.products;
  v_unit public.measure_unit;
  v_want boolean;
  v_face uuid;
  v_face_status public.product_status;
begin
  select * into v_item from public.products where id = p_item and type = 'stock';
  if v_item.id is null then
    raise exception 'product_not_found' using errcode = 'P0002';
  end if;

  foreach v_unit in array array['pack', 'piece']::public.measure_unit[] loop
    v_want := coalesce(
      v_item.status <> 'archived'
        and v_item.stock_role in ('sellable', 'both')
        and (v_item.sell_by = 'both' or (v_unit = 'pack') = (v_item.sell_by = 'pack')),
      false
    );

    v_face := null;
    v_face_status := null;
    select d.id, d.status into v_face, v_face_status
    from public.products d
    join public.product_components c on c.product_id = d.id and c.component_id = v_item.id
    where d.source_item_id = v_item.id and c.unit = v_unit
    limit 1;

    if v_want and v_face is null then
      insert into public.products (merchant_id, type, name, status, sold_directly, is_composite, source_item_id)
      values (
        v_item.merchant_id, 'flat',
        left(v_item.name, 96) || ' (' || case v_unit
          when 'pack' then coalesce(v_item.pack_unit_name, 'pack')
          else coalesce(v_item.base_unit_name, 'pc')
        end || ')',
        'draft', true, true, v_item.id
      )
      returning id into v_face;

      insert into public.product_components (product_id, merchant_id, component_id, qty, unit)
      values (v_face, v_item.merchant_id, v_item.id, 1, v_unit);
    elsif v_want and v_face_status = 'archived' then
      update public.products set status = 'draft', updated_at = now() where id = v_face;
    elsif not v_want and v_face_status = 'draft' then
      delete from public.products d
      where d.id = v_face
        and not exists (select 1 from public.product_components c where c.component_id = v_face);
    elsif not v_want and v_face_status in ('active', 'inactive') then
      update public.products set status = 'archived', updated_at = now() where id = v_face;
    end if;
  end loop;
end;
$$;

revoke execute on function public.ensure_register_faces(uuid) from public, anon, authenticated, service_role;
grant execute on function public.ensure_register_faces(uuid) to authenticated;

-- The trigger's own wrapper, so the inline Type toggle on the Inventory list is a plain update.
create or replace function private.sync_register_faces()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  perform public.ensure_register_faces(new.id);
  return null;
end;
$$;

revoke execute on function private.sync_register_faces() from public, anon, authenticated, service_role;

drop trigger if exists products_sync_register_faces on public.products;
create trigger products_sync_register_faces
  after insert or update of stock_role, sell_by, status on public.products
  for each row when (new.type = 'stock')
  execute function private.sync_register_faces();


-- 7. save_stock_item(payload): { item, group_name?, opening? }
--
-- The Inventory form's writer. `item` is a products row as JSON (id present to update). `group_name`
-- makes the variant's parent group inside the same transaction. `opening` — { packs, loose_units,
-- cost_per_pack } — is the form's optional stock on hand, written by add_inventory_stock
-- (20260929100100_stock_ledger.sql) so item and stock land together or not at all. Faces follow from
-- §6's trigger. qty_on_hand and cost_price are never written here; they belong to the ledger.
create or replace function public.save_stock_item(payload jsonb)
returns uuid
language plpgsql
security invoker
set search_path = ''
as $$
declare
  p public.products;
  v_id uuid;
  v_group uuid;
  v_group_name text := nullif(btrim(payload ->> 'group_name'), '');
begin
  p := jsonb_populate_record(null::public.products, payload -> 'item');
  v_group := p.group_id;

  if v_group is null and v_group_name is not null then
    insert into public.product_groups (merchant_id, name) values (p.merchant_id, v_group_name)
    on conflict (merchant_id, name) do update set name = excluded.name
    returning id into v_group;
  end if;

  if p.id is null then
    insert into public.products (
      merchant_id, type, name, category_id, subcategory_id, sku, barcode, description, tags, status,
      sold_directly, track_inventory, storage_location, reorder_threshold, expiry_alert_days, perishable,
      conversion_factor, pack_unit_name, base_unit_name, sell_by, stock_role, group_id, attributes,
      internal_notes
    ) values (
      p.merchant_id, 'stock', p.name, p.category_id, p.subcategory_id, p.sku, p.barcode, p.description,
      coalesce(p.tags, '{}'), coalesce(p.status, 'active'),
      false, true, p.storage_location, p.reorder_threshold, p.expiry_alert_days, coalesce(p.perishable, true),
      coalesce(p.conversion_factor, 1), p.pack_unit_name, p.base_unit_name, p.sell_by, p.stock_role, v_group,
      coalesce(p.attributes, '{}'), p.internal_notes
    )
    returning id into v_id;
  else
    update public.products set
      name = p.name, category_id = p.category_id, subcategory_id = p.subcategory_id, sku = p.sku,
      barcode = p.barcode, description = p.description, tags = coalesce(p.tags, '{}'),
      status = coalesce(p.status, status), storage_location = p.storage_location,
      reorder_threshold = p.reorder_threshold, expiry_alert_days = p.expiry_alert_days,
      perishable = coalesce(p.perishable, perishable), conversion_factor = coalesce(p.conversion_factor, 1),
      pack_unit_name = p.pack_unit_name, base_unit_name = p.base_unit_name, sell_by = p.sell_by,
      stock_role = p.stock_role, group_id = v_group, attributes = coalesce(p.attributes, '{}'),
      internal_notes = p.internal_notes, updated_at = now()
    where id = p.id and type = 'stock'
    returning id into v_id;

    if v_id is null then
      raise exception 'product_not_found' using errcode = 'P0002';
    end if;
  end if;

  if p.id is null and coalesce((payload -> 'opening' ->> 'packs')::integer, 0)
       + coalesce((payload -> 'opening' ->> 'loose_units')::numeric, 0) > 0 then
    perform public.add_inventory_stock((payload -> 'opening') || jsonb_build_object('product_id', v_id));
  end if;

  return v_id;
end;
$$;

revoke execute on function public.save_stock_item(jsonb) from public, anon, authenticated, service_role;
grant execute on function public.save_stock_item(jsonb) to authenticated;


-- Faces for every item already saved as Sellable or Both. Re-runnable: an item with its faces is left as
-- it is.
select public.ensure_register_faces(id) from public.products where type = 'stock';


-- ===== 20260929100100_stock_ledger.sql =====

-- The stock ledger: receipts, lots, cases, a row for every pack, and the movements that change them
-- (.claude/inventory-stock/Stock_Receiving.html, Inventory.html, instructions.txt).
--
-- 1. Enums: stock_movement_kind, write_off_reason, stock_lot_source.
-- 2. stock_receipts, stock_lots, stock_cases, stock_packs, stock_movements.
-- 3. Read views: stock_lot_lines (a lot with its balance) and stock_pick_queue (the pick order).
-- 4. The balance guard on products: qty_on_hand and cost_price belong to the ledger.
-- 5. Writers: save_receipt, add_inventory_stock, draw_stock, record_stock_movement, void_receipt.
-- 6. Policies: read-only for the client. Every write goes through a function in §5.
-- 7. Stock on hand from before this file becomes Inventory-added stock.
--
-- Quantities are base units throughout (tablets, pieces). Every physical pack is a row holding its own
-- remaining count, so loose units sold from two packs in two cases are two rows each draining — the
-- question instructions.txt asks. A lot is one receipt line (or one Inventory add): its lot number,
-- expiry, cost and the tiers it arrived in. What a lot has left is the sum of its packs, never stored.
--
-- ponytail: one row per pack. Receiving 1,000 packs writes 1,000 rows and issues 1,000 codes in a loop;
-- fine for a shop. A merchant receiving tens of thousands of packs a month wants sealed packs kept as a
-- count per lot, with rows made only as each is opened.

-- 1. Enums.
do $$
begin
  if to_regtype('public.stock_movement_kind') is null then
    create type public.stock_movement_kind as enum (
      'receive', 'sale', 'consume', 'adjust', 'write_off', 'return_supplier', 'void'
    );
  end if;
  if to_regtype('public.write_off_reason') is null then
    create type public.write_off_reason as enum ('expired', 'damaged', 'lost', 'other');
  end if;
  -- Where a lot came from: a Stock receipt, or the Inventory screen with no supplier behind it.
  if to_regtype('public.stock_lot_source') is null then
    create type public.stock_lot_source as enum ('stock', 'inventory');
  end if;
end
$$;


-- 2. Tables. Every key is composite with merchant_id, so a lot, case, pack or movement can only ever
-- point at rows of its own merchant. Keys are NO ACTION: receipts are voided, never deleted, and a
-- supplier or item with receipts refuses deletion (23503), which the screens turn into copy.

create table if not exists public.stock_receipts (
  id uuid primary key default gen_random_uuid(),
  merchant_id uuid not null references public.merchants (id) on delete cascade,
  code text not null,
  supplier_id uuid not null,
  invoice_no text,
  received_on date not null default current_date,
  -- Free text: the person at the door is not always a staff account. The signed-in account is on every
  -- movement instead.
  received_by text,
  location text,
  freight numeric(12, 2) not null default 0,
  notes text,
  voided_at timestamptz,
  void_reason text,
  created_by uuid,
  created_at timestamptz not null default now(),

  constraint stock_receipts_id_merchant unique (id, merchant_id),
  constraint stock_receipts_code_unique unique (merchant_id, code),
  constraint stock_receipts_supplier_fk foreign key (supplier_id, merchant_id)
    references public.suppliers (id, merchant_id),
  constraint stock_receipts_freight_non_negative check (freight >= 0),
  constraint stock_receipts_text_length check (
    (invoice_no is null or length(invoice_no) <= 64)
    and (received_by is null or length(received_by) <= 80)
    and (location is null or length(location) <= 120)
    and (notes is null or length(notes) <= 2000)
    and (void_reason is null or length(void_reason) <= 500)
  )
);

alter table public.stock_receipts enable row level security;
create index if not exists stock_receipts_supplier_id_idx on public.stock_receipts (supplier_id);

-- A receipt line, or one Inventory add. receipt_id is null exactly when source is 'inventory'.
create table if not exists public.stock_lots (
  id uuid primary key default gen_random_uuid(),
  merchant_id uuid not null references public.merchants (id) on delete cascade,
  source public.stock_lot_source not null,
  receipt_id uuid,
  position smallint not null default 0,
  product_id uuid not null,
  code text not null,
  -- The item's base units per pack on the day, so the lot still reads right after it changes.
  units_per_pack numeric(14, 4) not null,

  -- The tiers it arrived in (Stock_Receiving.html steps 2-4). Unit Load and Pallet are the record of
  -- how it came; Case also makes case rows.
  unit_loads integer,
  pallets_per_unit_load integer,
  unit_load_sscc text,
  pallets integer,
  cases_per_pallet integer,
  pallet_sscc text,
  cases integer,
  packs_per_case integer,
  cost_per_case numeric(14, 4),
  case_sscc text,

  packs_received integer not null default 0,
  -- One partial pack's worth, received loose.
  loose_units numeric(12, 3) not null default 0,
  qty_received numeric(12, 3) generated always as (packs_received * units_per_pack + loose_units) stored,

  cost_per_pack numeric(14, 4) not null default 0,
  line_cost numeric(12, 2) generated always as (
    round(cost_per_pack * (packs_received + loose_units / units_per_pack), 2)
  ) stored,
  -- This lot's share of the receipt's freight, and the landed cost per base unit that follows.
  freight_share numeric(12, 2) not null default 0,
  unit_cost numeric(14, 6) not null default 0,

  expires_on date,
  location text,
  notes text,
  created_at timestamptz not null default now(),

  constraint stock_lots_id_merchant unique (id, merchant_id),
  -- Lot numbers are never reused, typed or generated.
  constraint stock_lots_code_unique unique (merchant_id, code),
  constraint stock_lots_receipt_fk foreign key (receipt_id, merchant_id)
    references public.stock_receipts (id, merchant_id),
  constraint stock_lots_product_fk foreign key (product_id, merchant_id)
    references public.products (id, merchant_id),
  constraint stock_lots_source_receipt check ((source = 'stock') = (receipt_id is not null)),
  constraint stock_lots_code_length check (length(btrim(code)) between 1 and 64),
  constraint stock_lots_units_per_pack_positive check (units_per_pack > 0),
  constraint stock_lots_tiers_positive check (
    coalesce(unit_loads, 1) > 0 and coalesce(pallets_per_unit_load, 1) > 0
    and coalesce(pallets, 1) > 0 and coalesce(cases_per_pallet, 1) > 0
    and coalesce(cases, 1) > 0 and coalesce(packs_per_case, 1) > 0
  ),
  constraint stock_lots_case_tier check ((cases is null) = (packs_per_case is null)),
  constraint stock_lots_quantities check (
    packs_received >= 0 and loose_units >= 0 and loose_units < units_per_pack
    and packs_received * units_per_pack + loose_units > 0
  ),
  constraint stock_lots_costs_non_negative check (
    cost_per_pack >= 0 and coalesce(cost_per_case, 0) >= 0 and freight_share >= 0 and unit_cost >= 0
  ),
  constraint stock_lots_text_length check (
    (unit_load_sscc is null or length(unit_load_sscc) <= 64)
    and (pallet_sscc is null or length(pallet_sscc) <= 64)
    and (case_sscc is null or length(case_sscc) <= 64)
    and (location is null or length(location) <= 120)
    and (notes is null or length(notes) <= 2000)
  )
);

alter table public.stock_lots enable row level security;
create index if not exists stock_lots_receipt_id_idx on public.stock_lots (receipt_id);
create index if not exists stock_lots_product_id_idx on public.stock_lots (product_id, expires_on);

create table if not exists public.stock_cases (
  id uuid primary key default gen_random_uuid(),
  merchant_id uuid not null references public.merchants (id) on delete cascade,
  lot_id uuid not null,
  code text not null,
  sscc text,
  created_at timestamptz not null default now(),

  constraint stock_cases_id_merchant unique (id, merchant_id),
  constraint stock_cases_code_unique unique (merchant_id, code),
  constraint stock_cases_lot_fk foreign key (lot_id, merchant_id)
    references public.stock_lots (id, merchant_id),
  constraint stock_cases_sscc_length check (sscc is null or length(sscc) <= 64)
);

alter table public.stock_cases enable row level security;
create index if not exists stock_cases_lot_id_idx on public.stock_cases (lot_id);

-- A physical pack. Sealed while qty_remaining = units, open below it, empty at zero — derived, never
-- stored. product_id repeats the lot's so the pick order reads one table.
create table if not exists public.stock_packs (
  id uuid primary key default gen_random_uuid(),
  merchant_id uuid not null references public.merchants (id) on delete cascade,
  product_id uuid not null,
  lot_id uuid not null,
  case_id uuid,
  code text not null,
  -- The manufacturer's serial, when the pack carries one.
  serial text,
  units numeric(14, 4) not null,
  qty_remaining numeric(12, 3) not null,
  opened_at timestamptz,
  created_at timestamptz not null default now(),

  constraint stock_packs_id_merchant unique (id, merchant_id),
  constraint stock_packs_code_unique unique (merchant_id, code),
  -- A serial is unique for good, like a lot number. Nulls do not collide.
  constraint stock_packs_serial_unique unique (merchant_id, serial),
  constraint stock_packs_product_fk foreign key (product_id, merchant_id)
    references public.products (id, merchant_id),
  constraint stock_packs_lot_fk foreign key (lot_id, merchant_id)
    references public.stock_lots (id, merchant_id),
  constraint stock_packs_case_fk foreign key (case_id, merchant_id)
    references public.stock_cases (id, merchant_id),
  constraint stock_packs_serial_length check (serial is null or length(btrim(serial)) between 1 and 64),
  constraint stock_packs_remaining check (units > 0 and qty_remaining >= 0 and qty_remaining <= units)
);

alter table public.stock_packs enable row level security;
create index if not exists stock_packs_lot_id_idx on public.stock_packs (lot_id);
create index if not exists stock_packs_case_id_idx on public.stock_packs (case_id);
create index if not exists stock_packs_live_idx on public.stock_packs (product_id) where qty_remaining > 0;

-- The ledger. Append-only: nothing updates or deletes a movement. Each touches exactly one pack.
create table if not exists public.stock_movements (
  id uuid primary key default gen_random_uuid(),
  merchant_id uuid not null references public.merchants (id) on delete cascade,
  product_id uuid not null,
  lot_id uuid not null,
  pack_id uuid not null,
  kind public.stock_movement_kind not null,
  -- Signed, in base units.
  qty numeric(12, 3) not null,
  reason public.write_off_reason,
  note text,
  -- The document behind the movement: the receipt or lot code today, the sale later.
  ref text,
  -- The signed-in staff account. Null only on §7's backfill.
  created_by uuid,
  created_at timestamptz not null default now(),

  constraint stock_movements_product_fk foreign key (product_id, merchant_id)
    references public.products (id, merchant_id),
  constraint stock_movements_lot_fk foreign key (lot_id, merchant_id)
    references public.stock_lots (id, merchant_id),
  constraint stock_movements_pack_fk foreign key (pack_id, merchant_id)
    references public.stock_packs (id, merchant_id),
  constraint stock_movements_qty_non_zero check (qty <> 0),
  constraint stock_movements_note_length check (note is null or length(note) <= 500),
  constraint stock_movements_ref_length check (ref is null or length(ref) <= 64)
);

alter table public.stock_movements enable row level security;
create index if not exists stock_movements_product_id_idx on public.stock_movements (product_id, created_at desc);
create index if not exists stock_movements_lot_id_idx on public.stock_movements (lot_id);
create index if not exists stock_movements_pack_id_idx on public.stock_movements (pack_id);


-- 3. Read views. security_invoker, so each reads through the caller's RLS on the tables beneath.

-- A lot with what it has left: the Stock screen's rows and the Inventory screen's lot heads.
create or replace view public.stock_lot_lines with (security_invoker = true) as
select
  l.*,
  coalesce(b.qty_remaining, 0) as qty_remaining,
  coalesce(b.packs_total, 0) as packs_total,
  coalesce(b.packs_active, 0) as packs_active,
  coalesce(b.packs_open, 0) as packs_open
from public.stock_lots l
left join (
  select
    p.lot_id,
    sum(p.qty_remaining) as qty_remaining,
    count(*)::integer as packs_total,
    count(*) filter (where p.qty_remaining > 0)::integer as packs_active,
    count(*) filter (where p.qty_remaining > 0 and p.qty_remaining < p.units)::integer as packs_open
  from public.stock_packs p
  group by p.lot_id
) b on b.lot_id = l.id;

-- Every pack that can be drawn, ranked in the one pick order the app has:
--   1. open before sealed — finish what is already open
--   2. closest expiry first (FEFO); no expiry goes last
--   3. fewest units left
--   4. oldest lot first (FIFO)
--   5. pack code
-- An expired pack is never picked; it waits for a write-off. pick_rank orders loose-unit draws;
-- whole_rank orders sealed packs only, for a sale by the pack.
create or replace view public.stock_pick_queue with (security_invoker = true) as
select
  p.id as pack_id,
  p.merchant_id,
  p.product_id,
  p.lot_id,
  p.case_id,
  p.code,
  p.units,
  p.qty_remaining,
  l.expires_on,
  row_number() over (
    partition by p.product_id
    order by (p.qty_remaining < p.units) desc, l.expires_on asc nulls last, p.qty_remaining asc,
      l.created_at asc, p.code asc
  )::integer as pick_rank,
  case when p.qty_remaining = p.units then row_number() over (
    partition by p.product_id, p.qty_remaining = p.units
    order by l.expires_on asc nulls last, l.created_at asc, p.code asc
  )::integer end as whole_rank
from public.stock_packs p
join public.stock_lots l on l.id = p.lot_id
where p.qty_remaining > 0 and (l.expires_on is null or l.expires_on >= current_date);

revoke all on public.stock_lot_lines, public.stock_pick_queue from public, anon;
grant select on public.stock_lot_lines, public.stock_pick_queue to authenticated;


-- 4. The balance guard.
--
-- qty_on_hand is the sum of an item's packs and cost_price the weighted landed cost per base unit.
-- Only the functions in §5 write them, running as the owner. A client role writing either on a stock
-- item keeps the ledger's numbers instead of failing, so a stale edit screen still saves everything
-- else. Units per pack and archiving are refused while anything is on hand: the packs already counted
-- would stop meaning what they say.
create or replace function private.guard_stock_item()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.type <> 'stock' then
    return new;
  end if;

  if current_user in ('authenticated', 'anon') then
    if tg_op = 'INSERT' then
      new.qty_on_hand := 0;
      new.cost_price := null;
    else
      new.qty_on_hand := old.qty_on_hand;
      new.cost_price := old.cost_price;
    end if;
  end if;

  if tg_op = 'UPDATE' and coalesce(old.qty_on_hand, 0) > 0 then
    if new.status = 'archived' and old.status <> 'archived' then
      raise exception 'stock_on_hand'
        using errcode = '23514', detail = 'An item can be archived only once its stock is gone.';
    end if;
    if new.conversion_factor is distinct from old.conversion_factor then
      raise exception 'stock_item_units_locked'
        using errcode = '23514', detail = 'Units per pack change only while nothing is on hand.';
    end if;
  end if;

  return new;
end;
$$;

revoke execute on function private.guard_stock_item() from public, anon, authenticated, service_role;

drop trigger if exists products_guard_stock on public.products;
create trigger products_guard_stock
  before insert or update on public.products
  for each row execute function private.guard_stock_item();


-- 5. Writers.
--
-- Public and security definer, so the ledger tables need no write policy at all. Each carries
-- CLAUDE.md §6.2's three requirements: execute granted to authenticated alone, search_path pinned with
-- every name qualified, and private.assert_member() on the merchant it is about to touch. As owner they
-- bypass RLS, so every query in them names the merchant or reaches rows through one that did.
--
-- Lock order, everywhere: the item's products row first, then its packs. Two writers on one item queue
-- behind the first lock rather than deadlocking further down.

create or replace function private.recompute_stock(p_product uuid)
returns void
language sql
set search_path = ''
as $$
  update public.products p set
    qty_on_hand = s.qty,
    -- An empty item keeps its last cost, so a re-order still shows what it cost last time.
    cost_price = case when s.qty > 0 then round(s.value / s.qty, 2) else p.cost_price end
  from (
    select coalesce(sum(k.qty_remaining), 0) as qty, coalesce(sum(k.qty_remaining * l.unit_cost), 0) as value
    from public.stock_packs k
    join public.stock_lots l on l.id = k.lot_id
    where k.product_id = p_product
  ) s
  where p.id = p_product;
$$;

revoke execute on function private.recompute_stock(uuid) from public, anon, authenticated, service_role;

-- One lot, its cases and a row per pack, and a receive movement per pack. Shared by save_receipt,
-- add_inventory_stock and §7. The caller has locked the item and checked membership.
--
-- p_line: { cases?, packs_per_case?, cost_per_case?, case_sscc?, packs?, cost_per_pack?, loose_units?,
--           unit_loads?, pallets_per_unit_load?, unit_load_sscc?, pallets?, cases_per_pallet?,
--           pallet_sscc?, lot_code?, expires_on?, location?, notes?, serials?: text[] }
create or replace function private.create_lot(
  p_item public.products, p_receipt public.stock_receipts, p_position integer, p_line jsonb
)
returns public.stock_lots
language plpgsql
set search_path = ''
as $$
declare
  v_merchant uuid := p_item.merchant_id;
  v_on date := coalesce(p_receipt.received_on, current_date);
  v_upp numeric := coalesce(p_item.conversion_factor, 1);
  v_cases integer := nullif((p_line ->> 'cases')::integer, 0);
  v_per_case integer;
  v_packs integer;
  v_loose numeric := coalesce((p_line ->> 'loose_units')::numeric, 0);
  v_cost numeric;
  v_serials text[];
  v_lot public.stock_lots;
  v_case_id uuid;
  v_pack public.stock_packs;
  v_n integer := 0;
  i integer;
  j integer;
begin
  -- Case tier: cost is entered per case, and the pack cost follows.
  if v_cases is not null then
    v_per_case := (p_line ->> 'packs_per_case')::integer;
    if coalesce(v_per_case, 0) <= 0 or (p_line ->> 'cost_per_case') is null then
      raise exception 'receipt_line_case_tier' using errcode = '23514';
    end if;
    v_packs := v_cases * v_per_case;
    v_cost := (p_line ->> 'cost_per_case')::numeric / v_per_case;
  else
    v_packs := coalesce((p_line ->> 'packs')::integer, 0);
    v_cost := coalesce((p_line ->> 'cost_per_pack')::numeric, coalesce(p_item.cost_price, 0) * v_upp);
  end if;

  if v_packs < 0 or v_loose < 0 or v_loose >= v_upp or v_packs * v_upp + v_loose <= 0 then
    raise exception 'receipt_line_quantity' using errcode = '23514';
  end if;

  -- Has expiry: a received line needs its date. An Inventory add may leave it blank.
  if p_receipt.id is not null and p_item.perishable and (p_line ->> 'expires_on') is null then
    raise exception 'receipt_line_expiry_required' using errcode = '23514';
  end if;

  select coalesce(array_agg(btrim(s.serial) order by s.ord), '{}') into v_serials
  from jsonb_array_elements_text(coalesce(p_line -> 'serials', '[]')) with ordinality as s (serial, ord)
  where btrim(s.serial) <> '';
  if cardinality(v_serials) > v_packs then
    raise exception 'receipt_line_serial_count'
      using errcode = '23514', detail = 'More serial numbers than packs.';
  end if;

  -- issue_code only runs when no lot number was typed, so a typed one never burns a counter value.
  insert into public.stock_lots (
    merchant_id, source, receipt_id, position, product_id, code, units_per_pack,
    unit_loads, pallets_per_unit_load, unit_load_sscc, pallets, cases_per_pallet, pallet_sscc,
    cases, packs_per_case, cost_per_case, case_sscc,
    packs_received, loose_units, cost_per_pack, expires_on, location, notes
  ) values (
    v_merchant, case when p_receipt.id is null then 'inventory' else 'stock' end::public.stock_lot_source,
    p_receipt.id, p_position, p_item.id,
    coalesce(
      nullif(btrim(p_line ->> 'lot_code'), ''),
      private.issue_code(v_merchant, 'lot', 'LOT-' || to_char(v_on, 'YYYYMMDD') || '-', 3, 'public.stock_lots', 'code')
    ),
    v_upp,
    nullif((p_line ->> 'unit_loads')::integer, 0), nullif((p_line ->> 'pallets_per_unit_load')::integer, 0),
    nullif(btrim(p_line ->> 'unit_load_sscc'), ''),
    nullif((p_line ->> 'pallets')::integer, 0), nullif((p_line ->> 'cases_per_pallet')::integer, 0),
    nullif(btrim(p_line ->> 'pallet_sscc'), ''),
    v_cases, v_per_case, case when v_cases is not null then (p_line ->> 'cost_per_case')::numeric end,
    nullif(btrim(p_line ->> 'case_sscc'), ''),
    v_packs, v_loose, v_cost,
    (p_line ->> 'expires_on')::date,
    coalesce(nullif(btrim(p_line ->> 'location'), ''), p_receipt.location, p_item.storage_location),
    nullif(btrim(p_line ->> 'notes'), '')
  )
  returning * into v_lot;

  -- Packs in cases first, then loose packs, then the partial pack the loose units make.
  for i in 0 .. coalesce(v_cases, 0) loop
    v_case_id := null;
    if i > 0 then
      insert into public.stock_cases (merchant_id, lot_id, code, sscc)
      values (
        v_merchant, v_lot.id,
        private.issue_code(v_merchant, 'case', 'CS-', 4, 'public.stock_cases', 'code'),
        -- The one SSCC typed on the form labels the first case.
        case when i = 1 then v_lot.case_sscc end
      )
      returning id into v_case_id;
    end if;

    for j in 1 .. case when i = 0 then (case when v_cases is null then v_packs else 0 end) else v_per_case end loop
      v_n := v_n + 1;
      insert into public.stock_packs (merchant_id, product_id, lot_id, case_id, code, serial, units, qty_remaining)
      values (
        v_merchant, p_item.id, v_lot.id, v_case_id,
        private.issue_code(v_merchant, 'pack', 'PK-', 6, 'public.stock_packs', 'code'),
        v_serials[v_n], v_upp, v_upp
      )
      returning * into v_pack;

      insert into public.stock_movements (merchant_id, product_id, lot_id, pack_id, kind, qty, ref, created_by)
      values (v_merchant, p_item.id, v_lot.id, v_pack.id, 'receive', v_upp, coalesce(p_receipt.code, v_lot.code),
        (select auth.uid()));
    end loop;
  end loop;

  if v_loose > 0 then
    insert into public.stock_packs (merchant_id, product_id, lot_id, code, units, qty_remaining, opened_at)
    values (
      v_merchant, p_item.id, v_lot.id,
      private.issue_code(v_merchant, 'pack', 'PK-', 6, 'public.stock_packs', 'code'),
      v_upp, v_loose, now()
    )
    returning * into v_pack;

    insert into public.stock_movements (merchant_id, product_id, lot_id, pack_id, kind, qty, ref, created_by)
    values (v_merchant, p_item.id, v_lot.id, v_pack.id, 'receive', v_loose, coalesce(p_receipt.code, v_lot.code),
      (select auth.uid()));
  end if;

  -- No freight yet; save_receipt spreads it once every line is in.
  update public.stock_lots set unit_cost = line_cost / qty_received where id = v_lot.id
  returning * into v_lot;
  return v_lot;
end;
$$;

revoke execute on function private.create_lot(public.products, public.stock_receipts, integer, jsonb)
  from public, anon, authenticated, service_role;


-- save_receipt(payload): {
--   merchant_id, supplier_id, invoice_no?, received_on?, received_by?, location?, freight?, notes?,
--   lines: [{ product_id | new_item: { item, group_name? }, ...private.create_lot's p_line }]
-- }
-- Returns the receipt id. A saved receipt never changes; void_receipt and record_stock_movement make
-- the corrections.
create or replace function public.save_receipt(payload jsonb)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  r public.stock_receipts;
  v_merchant uuid := (payload ->> 'merchant_id')::uuid;
  v_supplier uuid := (payload ->> 'supplier_id')::uuid;
  v_freight numeric := coalesce((payload ->> 'freight')::numeric, 0);
  v_line jsonb;
  v_pos integer := 0;
  v_item public.products;
  v_item_id uuid;
  v_lot public.stock_lots;
  v_value_total numeric;
  v_qty_total numeric;
  v_left numeric;
  v_share numeric;
begin
  perform private.assert_member(v_merchant);

  if v_supplier is null or not exists (
    select 1 from public.suppliers s where s.id = v_supplier and s.merchant_id = v_merchant and s.active
  ) then
    raise exception 'supplier_not_available' using errcode = '23514';
  end if;
  if jsonb_array_length(coalesce(payload -> 'lines', '[]')) = 0 then
    raise exception 'receipt_has_no_lines' using errcode = '23514';
  end if;

  insert into public.stock_receipts (
    merchant_id, code, supplier_id, invoice_no, received_on, received_by, location, freight, notes, created_by
  ) values (
    v_merchant,
    private.issue_code(v_merchant, 'receipt', 'RC-', 4, 'public.stock_receipts', 'code'),
    v_supplier,
    nullif(btrim(payload ->> 'invoice_no'), ''),
    coalesce((payload ->> 'received_on')::date, current_date),
    nullif(btrim(payload ->> 'received_by'), ''),
    nullif(btrim(payload ->> 'location'), ''),
    v_freight,
    nullif(btrim(payload ->> 'notes'), ''),
    (select auth.uid())
  )
  returning * into r;

  for v_line in select e.value from jsonb_array_elements(payload -> 'lines') as e (value) loop
    v_pos := v_pos + 1;

    -- A new item is made inside the transaction, so an abandoned receipt leaves no orphan item.
    if v_line ? 'new_item' then
      v_item_id := public.save_stock_item(jsonb_build_object(
        'item', (v_line -> 'new_item' -> 'item') || jsonb_build_object('id', null, 'merchant_id', v_merchant),
        'group_name', v_line -> 'new_item' -> 'group_name'
      ));
    else
      v_item_id := (v_line ->> 'product_id')::uuid;
    end if;

    select * into v_item from public.products
    where id = v_item_id and merchant_id = v_merchant and type = 'stock' and status <> 'archived'
    for update;
    if v_item.id is null then
      raise exception 'stock_item_not_found' using errcode = 'P0002';
    end if;

    perform private.create_lot(v_item, r, v_pos, v_line);
  end loop;

  -- Freight: spread by line value, or by quantity when every line cost nothing. The last line takes
  -- what rounding leaves, so the shares add up to the freight exactly.
  select coalesce(sum(l.line_cost), 0), coalesce(sum(l.qty_received), 0) into v_value_total, v_qty_total
  from public.stock_lots l where l.receipt_id = r.id;
  v_left := v_freight;

  for v_lot in select * from public.stock_lots l where l.receipt_id = r.id order by l.position loop
    v_share := case
      when v_lot.position = v_pos then v_left
      when v_value_total > 0 then round(v_freight * v_lot.line_cost / v_value_total, 2)
      else round(v_freight * v_lot.qty_received / v_qty_total, 2)
    end;
    v_left := v_left - v_share;

    update public.stock_lots
    set freight_share = v_share, unit_cost = (v_lot.line_cost + v_share) / v_lot.qty_received
    where id = v_lot.id;
  end loop;

  perform private.recompute_stock(l.product_id)
  from (select distinct product_id from public.stock_lots where receipt_id = r.id) l;

  return r.id;
end;
$$;

revoke execute on function public.save_receipt(jsonb) from public, anon, authenticated, service_role;
grant execute on function public.save_receipt(jsonb) to authenticated;


-- add_inventory_stock(payload): { product_id, packs?, loose_units?, cost_per_pack?, expires_on?,
--                                 location?, notes? }
-- Stock added on the Inventory screen: a lot with no receipt and no supplier, drawn like any other.
-- Never listed on the Stock screen, which shows receipts. Returns the lot id.
create or replace function public.add_inventory_stock(payload jsonb)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_item public.products;
  v_lot public.stock_lots;
begin
  select * into v_item from public.products where id = (payload ->> 'product_id')::uuid and type = 'stock';
  if v_item.id is null then
    raise exception 'stock_item_not_found' using errcode = 'P0002';
  end if;
  perform private.assert_member(v_item.merchant_id);

  select * into v_item from public.products where id = v_item.id for update;
  if v_item.status = 'archived' then
    raise exception 'stock_item_not_found' using errcode = 'P0002';
  end if;

  v_lot := private.create_lot(v_item, null, 0, payload - 'cases' - 'serials' - 'lot_code');
  perform private.recompute_stock(v_item.id);
  return v_lot.id;
end;
$$;

revoke execute on function public.add_inventory_stock(jsonb) from public, anon, authenticated, service_role;
grant execute on function public.add_inventory_stock(jsonb) to authenticated;


-- draw_stock(payload): { product_id, qty, mode: 'base' | 'pack', kind: 'sale' | 'consume', ref? }
--
-- Takes stock out in the pick order (§3). 'base' drains qty base units, finishing open packs, opening
-- sealed ones and spilling across packs and cases as it goes. 'pack' takes qty whole sealed packs.
-- One movement per pack touched. Short stock raises insufficient_stock and draws nothing. Returns
-- [{ pack_id, code, qty }] for the caller's record. The Register (a sale) and recipes (consume) call it.
create or replace function public.draw_stock(payload jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_item public.products;
  v_qty numeric := (payload ->> 'qty')::numeric;
  v_mode text := coalesce(payload ->> 'mode', 'base');
  v_kind public.stock_movement_kind := coalesce(payload ->> 'kind', 'sale')::public.stock_movement_kind;
  v_ref text := nullif(btrim(payload ->> 'ref'), '');
  v_left numeric;
  v_take numeric;
  q record;
  v_out jsonb := '[]';
begin
  if v_kind not in ('sale', 'consume') or v_mode not in ('base', 'pack')
     or v_qty is null or v_qty <= 0 or (v_mode = 'pack' and v_qty <> trunc(v_qty)) then
    raise exception 'draw_invalid' using errcode = '22023';
  end if;

  select * into v_item from public.products where id = (payload ->> 'product_id')::uuid and type = 'stock';
  if v_item.id is null then
    raise exception 'stock_item_not_found' using errcode = 'P0002';
  end if;
  perform private.assert_member(v_item.merchant_id);
  -- The item lock serializes draws on it, so the queue read below cannot change underneath.
  perform 1 from public.products where id = v_item.id for update;

  v_left := v_qty;
  for q in
    select k.pack_id, k.code, k.lot_id, k.qty_remaining
    from public.stock_pick_queue k
    where k.product_id = v_item.id and (v_mode = 'base' or k.whole_rank is not null)
    order by case when v_mode = 'base' then k.pick_rank else k.whole_rank end
  loop
    exit when v_left <= 0;
    v_take := case when v_mode = 'base' then least(v_left, q.qty_remaining) else q.qty_remaining end;

    update public.stock_packs
    set qty_remaining = qty_remaining - v_take, opened_at = coalesce(opened_at, now())
    where id = q.pack_id;

    insert into public.stock_movements (merchant_id, product_id, lot_id, pack_id, kind, qty, ref, created_by)
    values (v_item.merchant_id, v_item.id, q.lot_id, q.pack_id, v_kind, -v_take, v_ref, (select auth.uid()));

    v_out := v_out || jsonb_build_object('pack_id', q.pack_id, 'code', q.code, 'qty', v_take);
    v_left := v_left - case when v_mode = 'base' then v_take else 1 end;
  end loop;

  if v_left > 0 then
    raise exception 'insufficient_stock' using errcode = '23514';
  end if;

  perform private.recompute_stock(v_item.id);
  return v_out;
end;
$$;

revoke execute on function public.draw_stock(jsonb) from public, anon, authenticated, service_role;
grant execute on function public.draw_stock(jsonb) to authenticated;


-- record_stock_movement(payload): { kind, pack_id, qty, reason?, note? }
--
-- A pack's row actions: adjust (signed qty, note required), write_off (amount removed, reason required,
-- and a note when the reason is Other), return_supplier (amount removed; only stock that came on a
-- receipt, which names the supplier).
create or replace function public.record_stock_movement(payload jsonb)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_kind public.stock_movement_kind := (payload ->> 'kind')::public.stock_movement_kind;
  v_qty numeric := (payload ->> 'qty')::numeric;
  v_reason public.write_off_reason := (payload ->> 'reason')::public.write_off_reason;
  v_note text := nullif(btrim(payload ->> 'note'), '');
  v_pack public.stock_packs;
  v_lot public.stock_lots;
begin
  if v_kind not in ('adjust', 'write_off', 'return_supplier') then
    raise exception 'stock_movement_kind_invalid' using errcode = '22023';
  end if;
  if v_qty is null or v_qty = 0 or (v_kind <> 'adjust' and v_qty < 0) then
    raise exception 'stock_movement_qty_invalid' using errcode = '22023';
  end if;
  if v_kind = 'adjust' and v_note is null then
    raise exception 'stock_movement_note_required' using errcode = '23514';
  end if;
  if v_kind = 'write_off' and (v_reason is null or (v_reason = 'other' and v_note is null)) then
    raise exception 'write_off_reason_required' using errcode = '23514';
  end if;

  -- Write-offs and returns take the amount removed; the ledger stores it negative.
  if v_kind <> 'adjust' then
    v_qty := -v_qty;
  end if;
  if v_kind <> 'write_off' then
    v_reason := null;
  end if;

  select * into v_pack from public.stock_packs where id = (payload ->> 'pack_id')::uuid;
  if v_pack.id is null then
    raise exception 'stock_target_not_found' using errcode = 'P0002';
  end if;
  perform private.assert_member(v_pack.merchant_id);

  perform 1 from public.products where id = v_pack.product_id for update;
  select * into v_pack from public.stock_packs where id = v_pack.id for update;
  select * into v_lot from public.stock_lots where id = v_pack.lot_id;

  if exists (select 1 from public.stock_receipts sr where sr.id = v_lot.receipt_id and sr.voided_at is not null) then
    raise exception 'receipt_voided' using errcode = '23514';
  end if;
  if v_kind = 'return_supplier' and v_lot.source <> 'stock' then
    raise exception 'receipt_has_no_supplier' using errcode = '23514';
  end if;
  if v_pack.qty_remaining + v_qty < 0 then
    raise exception 'insufficient_stock' using errcode = '23514';
  end if;
  if v_pack.qty_remaining + v_qty > v_pack.units then
    raise exception 'pack_over_capacity' using errcode = '23514';
  end if;

  update public.stock_packs
  set qty_remaining = qty_remaining + v_qty,
      opened_at = case when qty_remaining + v_qty < units then coalesce(opened_at, now()) else opened_at end
  where id = v_pack.id;

  insert into public.stock_movements (merchant_id, product_id, lot_id, pack_id, kind, qty, reason, note, ref, created_by)
  values (
    v_pack.merchant_id, v_pack.product_id, v_lot.id, v_pack.id, v_kind, v_qty, v_reason, v_note,
    coalesce((select sr.code from public.stock_receipts sr where sr.id = v_lot.receipt_id), v_lot.code),
    (select auth.uid())
  );

  perform private.recompute_stock(v_pack.product_id);
end;
$$;

revoke execute on function public.record_stock_movement(jsonb) from public, anon, authenticated, service_role;
grant execute on function public.record_stock_movement(jsonb) to authenticated;


-- void_receipt: takes every pack of a receipt back to zero with a void movement each. Allowed only while
-- nothing but the receipt itself has touched its stock; after that, corrections are adjustments, which
-- keep the history.
create or replace function public.void_receipt(p_receipt uuid, p_reason text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  r public.stock_receipts;
begin
  select * into r from public.stock_receipts where id = p_receipt;
  if r.id is null then
    raise exception 'receipt_not_found' using errcode = 'P0002';
  end if;
  perform private.assert_member(r.merchant_id);

  perform 1 from public.products
  where id in (select l.product_id from public.stock_lots l where l.receipt_id = r.id)
  order by id
  for update;

  select * into r from public.stock_receipts where id = p_receipt for update;
  if r.voided_at is not null then
    raise exception 'receipt_voided' using errcode = '23514';
  end if;

  if exists (
    select 1 from public.stock_movements m
    join public.stock_lots l on l.id = m.lot_id
    where l.receipt_id = r.id and m.kind <> 'receive'
  ) then
    raise exception 'receipt_in_use'
      using errcode = '23514', detail = 'Stock from this receipt has already moved.';
  end if;

  insert into public.stock_movements (merchant_id, product_id, lot_id, pack_id, kind, qty, note, ref, created_by)
  select k.merchant_id, k.product_id, k.lot_id, k.id, 'void', -k.qty_remaining, nullif(btrim(p_reason), ''),
    r.code, (select auth.uid())
  from public.stock_packs k
  join public.stock_lots l on l.id = k.lot_id
  where l.receipt_id = r.id and k.qty_remaining > 0;

  update public.stock_packs set qty_remaining = 0
  where lot_id in (select l.id from public.stock_lots l where l.receipt_id = r.id);

  update public.stock_receipts set voided_at = now(), void_reason = nullif(btrim(p_reason), '')
  where id = r.id;

  perform private.recompute_stock(l.product_id)
  from (select distinct product_id from public.stock_lots where receipt_id = r.id) l;
end;
$$;

revoke execute on function public.void_receipt(uuid, text) from public, anon, authenticated, service_role;
grant execute on function public.void_receipt(uuid, text) to authenticated;


-- 6. Policies: select only, and §5 is the only way in.
do $$
declare
  t text;
begin
  foreach t in array array['stock_receipts', 'stock_lots', 'stock_cases', 'stock_packs', 'stock_movements'] loop
    execute format('drop policy if exists %I on public.%I', t || '_select_own_merchant', t);
    execute format(
      'create policy %I on public.%I for select to authenticated
         using (merchant_id in (select private.current_merchant_ids()))',
      t || '_select_own_merchant', t
    );
  end loop;
end
$$;


-- 7. Stock on hand from before this file.
--
-- Reverting the older ledger left each item's qty_on_hand as a plain number. Every stock item holding
-- some and no lot gets it back as Inventory-added stock, costed at its current cost_price, so nothing
-- disappears and every unit is on a pack from here on. An item left negative or null is set to zero.
-- Re-runnable: an item that already has a lot is skipped.
do $$
declare
  p public.products;
  v_upp numeric;
  v_packs integer;
begin
  for p in
    select * from public.products pr
    where pr.type = 'stock' and pr.qty_on_hand > 0
      and not exists (select 1 from public.stock_lots l where l.product_id = pr.id)
    order by pr.merchant_id, pr.created_at, pr.id
  loop
    v_upp := coalesce(p.conversion_factor, 1);
    v_packs := floor(p.qty_on_hand / v_upp);
    perform private.create_lot(p, null, 0, jsonb_build_object(
      'packs', v_packs,
      'loose_units', p.qty_on_hand - v_packs * v_upp,
      'cost_per_pack', coalesce(p.cost_price, 0) * v_upp,
      'expires_on', p.expiry_date,
      'notes', 'Stock on hand before the ledger'
    ));
  end loop;

  perform private.recompute_stock(pr.id) from public.products pr where pr.type = 'stock';
end
$$;


-- ===== 20260930100000_receipt_inputs.sql =====

-- The New stock receipt's inputs, as the merchant fills them in (.claude/my-prompt-this-session.md).
--
-- 1. A receipt's supplier is optional. The app asks for a supplier and a date together or neither;
--    received_on stays not null and falls back to today.
-- 2. A blank lot number stays blank. Nothing issues LOT-… any more; the unique constraint allows many
--    nulls, and stock_lots_code_length passes on null.
-- 3. A lot keeps the packs it was expected to hold (packs_expected) beside the packs that arrived
--    (packs_received, which the stock is made from), and the base units counted in one pack
--    (units_per_pack_received) beside the item's own units_per_pack. Both are a record only.
-- 4. The cost per base unit is the merchant's when they type one; otherwise it is the pack cost over the
--    units. The receipt's freight (Shipping cost) is recorded and no longer spread into unit_cost, so
--    freight_share stays 0 on new lots.
--
-- Rejected: a server check pairing supplier and date. received_on has always defaulted to today, and a
-- receipt with a supplier and no typed date is still a delivery that happened today.

alter table public.stock_receipts alter column supplier_id drop not null;

alter table public.stock_lots alter column code drop not null;
alter table public.stock_lots add column if not exists packs_expected integer;
alter table public.stock_lots add column if not exists units_per_pack_received numeric(14, 4);
alter table public.stock_lots drop constraint if exists stock_lots_expected_positive;
alter table public.stock_lots add constraint stock_lots_expected_positive check (
  coalesce(packs_expected, 1) > 0 and coalesce(units_per_pack_received, 1) > 0
);

-- Explicit, as in every migration (CLAUDE.md §6.1); both tables already have it.
alter table public.stock_receipts enable row level security;
alter table public.stock_lots enable row level security;


-- One lot, its cases and a row per pack, and a receive movement per pack. Shared by save_receipt,
-- add_inventory_stock and §7 of 20260929100100_stock_ledger.sql. The caller has locked the item and
-- checked membership.
--
-- p_line: { cases?, packs_per_case?, cost_per_case?, case_sscc?, packs_expected?, packs?, cost_per_pack?,
--           unit_cost?, units_per_pack_received?, loose_units?, unit_loads?, pallets_per_unit_load?,
--           unit_load_sscc?, pallets?, cases_per_pallet?, pallet_sscc?, lot_code?, expires_on?, location?,
--           notes?, serials?: text[] }
-- `packs` is what arrived; blank, the expected count (packs_expected, or cases × packs_per_case) is
-- taken as received. Packs fill the cases in order, so a short delivery leaves the last cases short.
create or replace function private.create_lot(
  p_item public.products, p_receipt public.stock_receipts, p_position integer, p_line jsonb
)
returns public.stock_lots
language plpgsql
set search_path = ''
as $$
declare
  v_merchant uuid := p_item.merchant_id;
  v_upp numeric := coalesce(p_item.conversion_factor, 1);
  v_cases integer := nullif((p_line ->> 'cases')::integer, 0);
  v_per_case integer;
  v_expected integer := (p_line ->> 'packs_expected')::integer;
  v_packs integer;
  v_loose numeric := coalesce((p_line ->> 'loose_units')::numeric, 0);
  v_cost numeric;
  v_serials text[];
  v_lot public.stock_lots;
  v_case_id uuid;
  v_pack public.stock_packs;
begin
  -- Case tier: cost is entered per case, and the pack cost and the expected count follow.
  if v_cases is not null then
    v_per_case := (p_line ->> 'packs_per_case')::integer;
    if coalesce(v_per_case, 0) <= 0 or (p_line ->> 'cost_per_case') is null then
      raise exception 'receipt_line_case_tier' using errcode = '23514';
    end if;
    v_expected := v_cases * v_per_case;
    v_cost := (p_line ->> 'cost_per_case')::numeric / v_per_case;
  else
    v_cost := coalesce((p_line ->> 'cost_per_pack')::numeric, coalesce(p_item.cost_price, 0) * v_upp);
  end if;
  v_packs := coalesce((p_line ->> 'packs')::integer, v_expected, 0);

  if v_packs < 0 or v_loose < 0 or v_loose >= v_upp or v_packs * v_upp + v_loose <= 0 then
    raise exception 'receipt_line_quantity' using errcode = '23514';
  end if;

  -- Has expiry: a received line needs its date. An Inventory add may leave it blank.
  if p_receipt.id is not null and p_item.perishable and (p_line ->> 'expires_on') is null then
    raise exception 'receipt_line_expiry_required' using errcode = '23514';
  end if;

  select coalesce(array_agg(btrim(s.serial) order by s.ord), '{}') into v_serials
  from jsonb_array_elements_text(coalesce(p_line -> 'serials', '[]')) with ordinality as s (serial, ord)
  where btrim(s.serial) <> '';
  if cardinality(v_serials) > v_packs then
    raise exception 'receipt_line_serial_count'
      using errcode = '23514', detail = 'More serial numbers than packs.';
  end if;

  insert into public.stock_lots (
    merchant_id, source, receipt_id, position, product_id, code, units_per_pack, units_per_pack_received,
    unit_loads, pallets_per_unit_load, unit_load_sscc, pallets, cases_per_pallet, pallet_sscc,
    cases, packs_per_case, cost_per_case, case_sscc,
    packs_expected, packs_received, loose_units, cost_per_pack, expires_on, location, notes
  ) values (
    v_merchant, case when p_receipt.id is null then 'inventory' else 'stock' end::public.stock_lot_source,
    p_receipt.id, p_position, p_item.id,
    nullif(btrim(p_line ->> 'lot_code'), ''),
    v_upp, nullif((p_line ->> 'units_per_pack_received')::numeric, 0),
    nullif((p_line ->> 'unit_loads')::integer, 0), nullif((p_line ->> 'pallets_per_unit_load')::integer, 0),
    nullif(btrim(p_line ->> 'unit_load_sscc'), ''),
    nullif((p_line ->> 'pallets')::integer, 0), nullif((p_line ->> 'cases_per_pallet')::integer, 0),
    nullif(btrim(p_line ->> 'pallet_sscc'), ''),
    v_cases, v_per_case, case when v_cases is not null then (p_line ->> 'cost_per_case')::numeric end,
    nullif(btrim(p_line ->> 'case_sscc'), ''),
    nullif(v_expected, 0), v_packs, v_loose, v_cost,
    (p_line ->> 'expires_on')::date,
    coalesce(nullif(btrim(p_line ->> 'location'), ''), p_receipt.location, p_item.storage_location),
    nullif(btrim(p_line ->> 'notes'), '')
  )
  returning * into v_lot;

  -- Packs fill the cases in order; any past the last case are loose. A case row is made when its first
  -- pack is, so a case that never arrived has none.
  v_case_id := null;
  for n in 1 .. v_packs loop
    if v_cases is not null and (n - 1) % v_per_case = 0 then
      v_case_id := null;
      if (n - 1) / v_per_case < v_cases then
        insert into public.stock_cases (merchant_id, lot_id, code, sscc)
        values (
          v_merchant, v_lot.id,
          private.issue_code(v_merchant, 'case', 'CS-', 4, 'public.stock_cases', 'code'),
          -- The one SSCC typed on the form labels the first case.
          case when n = 1 then v_lot.case_sscc end
        )
        returning id into v_case_id;
      end if;
    end if;

    insert into public.stock_packs (merchant_id, product_id, lot_id, case_id, code, serial, units, qty_remaining)
    values (
      v_merchant, p_item.id, v_lot.id, v_case_id,
      private.issue_code(v_merchant, 'pack', 'PK-', 6, 'public.stock_packs', 'code'),
      v_serials[n], v_upp, v_upp
    )
    returning * into v_pack;

    -- A lot with no number and no receipt (an Inventory add) is referred to by its pack.
    insert into public.stock_movements (merchant_id, product_id, lot_id, pack_id, kind, qty, ref, created_by)
    values (v_merchant, p_item.id, v_lot.id, v_pack.id, 'receive', v_upp,
      coalesce(p_receipt.code, v_lot.code, v_pack.code), (select auth.uid()));
  end loop;

  if v_loose > 0 then
    insert into public.stock_packs (merchant_id, product_id, lot_id, code, units, qty_remaining, opened_at)
    values (
      v_merchant, p_item.id, v_lot.id,
      private.issue_code(v_merchant, 'pack', 'PK-', 6, 'public.stock_packs', 'code'),
      v_upp, v_loose, now()
    )
    returning * into v_pack;

    insert into public.stock_movements (merchant_id, product_id, lot_id, pack_id, kind, qty, ref, created_by)
    values (v_merchant, p_item.id, v_lot.id, v_pack.id, 'receive', v_loose,
      coalesce(p_receipt.code, v_lot.code, v_pack.code), (select auth.uid()));
  end if;

  -- The merchant's cost per base unit is final; blank, it is the lot's cost over its units.
  update public.stock_lots
  set unit_cost = coalesce((p_line ->> 'unit_cost')::numeric, line_cost / qty_received)
  where id = v_lot.id
  returning * into v_lot;
  return v_lot;
end;
$$;

revoke execute on function private.create_lot(public.products, public.stock_receipts, integer, jsonb)
  from public, anon, authenticated, service_role;


-- save_receipt(payload): {
--   merchant_id, supplier_id?, invoice_no?, received_on?, received_by?, location?, freight?, notes?,
--   lines: [{ product_id | new_item: { item, group_name? }, ...private.create_lot's p_line }]
-- }
-- Returns the receipt id. A saved receipt never changes; void_receipt and record_stock_movement make
-- the corrections.
create or replace function public.save_receipt(payload jsonb)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  r public.stock_receipts;
  v_merchant uuid := (payload ->> 'merchant_id')::uuid;
  v_supplier uuid := (payload ->> 'supplier_id')::uuid;
  v_line jsonb;
  v_pos integer := 0;
  v_item public.products;
  v_item_id uuid;
begin
  perform private.assert_member(v_merchant);

  -- No supplier is allowed; a named one must be this merchant's and active.
  if v_supplier is not null and not exists (
    select 1 from public.suppliers s where s.id = v_supplier and s.merchant_id = v_merchant and s.active
  ) then
    raise exception 'supplier_not_available' using errcode = '23514';
  end if;
  if jsonb_array_length(coalesce(payload -> 'lines', '[]')) = 0 then
    raise exception 'receipt_has_no_lines' using errcode = '23514';
  end if;

  insert into public.stock_receipts (
    merchant_id, code, supplier_id, invoice_no, received_on, received_by, location, freight, notes, created_by
  ) values (
    v_merchant,
    private.issue_code(v_merchant, 'receipt', 'RC-', 4, 'public.stock_receipts', 'code'),
    v_supplier,
    nullif(btrim(payload ->> 'invoice_no'), ''),
    coalesce((payload ->> 'received_on')::date, current_date),
    nullif(btrim(payload ->> 'received_by'), ''),
    nullif(btrim(payload ->> 'location'), ''),
    coalesce((payload ->> 'freight')::numeric, 0),
    nullif(btrim(payload ->> 'notes'), ''),
    (select auth.uid())
  )
  returning * into r;

  for v_line in select e.value from jsonb_array_elements(payload -> 'lines') as e (value) loop
    v_pos := v_pos + 1;

    -- A new item is made inside the transaction, so an abandoned receipt leaves no orphan item.
    if v_line ? 'new_item' then
      v_item_id := public.save_stock_item(jsonb_build_object(
        'item', (v_line -> 'new_item' -> 'item') || jsonb_build_object('id', null, 'merchant_id', v_merchant),
        'group_name', v_line -> 'new_item' -> 'group_name'
      ));
    else
      v_item_id := (v_line ->> 'product_id')::uuid;
    end if;

    select * into v_item from public.products
    where id = v_item_id and merchant_id = v_merchant and type = 'stock' and status <> 'archived'
    for update;
    if v_item.id is null then
      raise exception 'stock_item_not_found' using errcode = 'P0002';
    end if;

    perform private.create_lot(v_item, r, v_pos, v_line);
  end loop;

  perform private.recompute_stock(l.product_id)
  from (select distinct product_id from public.stock_lots where receipt_id = r.id) l;

  return r.id;
end;
$$;

revoke execute on function public.save_receipt(jsonb) from public, anon, authenticated, service_role;
grant execute on function public.save_receipt(jsonb) to authenticated;


-- ===== 20260930110000_sales.sql =====

-- Sales: what the Register writes and the Receipts screen lists (.claude/register-receipts/context.md).
--
-- 1. sales and sale_lines.
-- 2. record_sale: a whole sale in one call — lines, totals, and every stock draw it causes.
-- 3. void_sale: puts back every unit a sale drew, pack by pack.
-- 4. Policies: read-only for the client, like the stock ledger. Every write goes through §2 or §3.
--
-- Cash only, and prices include tax: a line's tax is the part of its total its tax class makes up,
-- total × rate / (100 + rate), rounded per line. Price, name and rate are read here, never taken from the
-- client, and kept on the line so a later price change or a deleted product leaves the receipt as sold.
--
-- The stock side is 20260929100100_stock_ledger.sql's draw_stock, unchanged. Every movement a sale makes
-- carries the sale's code as its ref, which is how void_sale and the receipt's "Stock drawn" find them.


-- 1. Tables.
create table if not exists public.sales (
  id uuid primary key default gen_random_uuid(),
  merchant_id uuid not null references public.merchants (id) on delete cascade,
  code text not null,
  -- Made by the Register once per sale, so a request retried after a dropped connection returns the sale
  -- already made instead of charging and drawing twice.
  client_key text not null,
  total numeric(12, 2) not null,
  -- The tax already inside total.
  tax_total numeric(12, 2) not null,
  tendered numeric(12, 2) not null,
  change_due numeric(12, 2) generated always as (tendered - total) stored,
  voided_at timestamptz,
  void_reason text,
  -- The signed-in staff account.
  created_by uuid,
  created_at timestamptz not null default now(),

  constraint sales_id_merchant unique (id, merchant_id),
  constraint sales_code_unique unique (merchant_id, code),
  constraint sales_client_key_unique unique (merchant_id, client_key),
  constraint sales_amounts check (total >= 0 and tax_total >= 0 and tax_total <= total and tendered >= total),
  constraint sales_text_length check (
    length(client_key) between 1 and 64 and (void_reason is null or length(void_reason) <= 500)
  )
);

alter table public.sales enable row level security;
create index if not exists sales_created_at_idx on public.sales (merchant_id, created_at desc);

create table if not exists public.sale_lines (
  id uuid primary key default gen_random_uuid(),
  merchant_id uuid not null references public.merchants (id) on delete cascade,
  sale_id uuid not null,
  position smallint not null default 0,
  -- Nulled, not refused, when the product is deleted: the line keeps its own name and price.
  product_id uuid,
  name text not null,
  unit_price numeric(12, 2) not null,
  qty numeric(12, 3) not null,
  tax_rate numeric(5, 2) not null default 0,
  line_total numeric(12, 2) generated always as (round(unit_price * qty, 2)) stored,

  constraint sale_lines_sale_fk foreign key (sale_id, merchant_id)
    references public.sales (id, merchant_id) on delete cascade,
  constraint sale_lines_product_fk foreign key (product_id, merchant_id)
    references public.products (id, merchant_id) on delete set null (product_id),
  constraint sale_lines_qty_positive check (qty > 0),
  constraint sale_lines_amounts check (unit_price >= 0 and tax_rate between 0 and 100)
);

alter table public.sale_lines enable row level security;
create index if not exists sale_lines_sale_id_idx on public.sale_lines (sale_id);
create index if not exists sale_lines_product_id_idx on public.sale_lines (product_id);
-- void_sale and the receipt's "Stock drawn" find a sale's movements by its code.
create index if not exists stock_movements_ref_idx on public.stock_movements (merchant_id, ref);


-- 2. record_sale(payload): { merchant_id, client_key, tendered, lines: [{ product_id, qty }] }
--
-- Sells only what the Register lists: a Products-screen row — flat, active, sold directly, priced. Any
-- other raises sale_product_unavailable with the product's name in detail.
--
-- Stock follows the recipe tree down from each line: a component that is a stock item is drawn, one that
-- is another flat product is walked in turn, and quantities multiply on the way down. A face's own item
-- is drawn as a sale; everything a recipe uses is drawn as consume. A component counted in packs takes
-- whole sealed packs, or its base units when the total is a fraction of a pack; any other unit is base
-- units. A flat product with no components draws nothing.
--
-- Draws are summed per item and made in item order, so two sales sharing items lock them in the same
-- order. Short stock raises insufficient_stock with the item's name in detail, and nothing of the sale is
-- kept. Short cash raises tendered_short. Returns { id, code, total, tax_total, change_due }.
create or replace function public.record_sale(payload jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_merchant uuid := (payload ->> 'merchant_id')::uuid;
  v_key text := nullif(btrim(payload ->> 'client_key'), '');
  v_tendered numeric := (payload ->> 'tendered')::numeric;
  v_lines jsonb := payload -> 'lines';
  v_sale public.sales;
  v_bad text;
  v_total numeric;
  v_tax numeric;
  d record;
begin
  perform private.assert_member(v_merchant);

  if v_key is null or jsonb_typeof(v_lines) is distinct from 'array' or jsonb_array_length(v_lines) = 0
     or exists (select 1 from jsonb_to_recordset(v_lines) as l (product_id uuid, qty numeric)
                where l.product_id is null or l.qty is null or l.qty <= 0) then
    raise exception 'sale_invalid' using errcode = '22023';
  end if;

  select * into v_sale from public.sales where merchant_id = v_merchant and client_key = v_key;
  if v_sale.id is not null then
    return jsonb_build_object('id', v_sale.id, 'code', v_sale.code, 'total', v_sale.total,
      'tax_total', v_sale.tax_total, 'change_due', v_sale.change_due);
  end if;

  select coalesce(p.name, '') into v_bad
  from jsonb_to_recordset(v_lines) as l (product_id uuid, qty numeric)
  left join public.products p on p.id = l.product_id and p.merchant_id = v_merchant
  where p.id is null or p.type <> 'flat' or p.status <> 'active' or not p.sold_directly or p.selling_price is null
  limit 1;
  if found then
    raise exception 'sale_product_unavailable' using errcode = '23514', detail = v_bad;
  end if;

  select
    coalesce(sum(round(p.selling_price * l.qty, 2)), 0),
    coalesce(sum(round(round(p.selling_price * l.qty, 2) * coalesce(t.rate, 0) / (100 + coalesce(t.rate, 0)), 2)), 0)
  into v_total, v_tax
  from jsonb_to_recordset(v_lines) as l (product_id uuid, qty numeric)
  join public.products p on p.id = l.product_id
  left join public.tax_classes t on t.id = p.tax_class_id;

  if v_tendered is null or v_tendered < v_total then
    raise exception 'tendered_short' using errcode = '23514';
  end if;

  insert into public.sales (merchant_id, code, client_key, total, tax_total, tendered, created_by)
  values (
    v_merchant, private.issue_code(v_merchant, 'sale', 'SL-', 5, 'public.sales', 'code'), v_key,
    v_total, v_tax, v_tendered, (select auth.uid())
  )
  returning * into v_sale;

  insert into public.sale_lines (merchant_id, sale_id, position, product_id, name, unit_price, qty, tax_rate)
  select v_merchant, v_sale.id, l.n - 1, p.id, p.name, p.selling_price, l.qty, coalesce(t.rate, 0)
  from rows from (jsonb_to_recordset(v_lines) as (product_id uuid, qty numeric)) with ordinality as l (product_id, qty, n)
  join public.products p on p.id = l.product_id
  left join public.tax_classes t on t.id = p.tax_class_id;

  for d in
    with recursive walk (line_product, product_id, qty, unit, depth) as (
      select l.product_id, c.component_id, l.qty * c.qty, c.unit, 1
      from jsonb_to_recordset(v_lines) as l (product_id uuid, qty numeric)
      join public.product_components c on c.product_id = l.product_id
      union all
      select w.line_product, c.component_id, w.qty * c.qty, c.unit, w.depth + 1
      from walk w
      join public.products p on p.id = w.product_id and p.type = 'flat'
      join public.product_components c on c.product_id = w.product_id
      -- assert_no_bundle_cycle keeps the tree acyclic; this only stops a runaway walk if it ever isn't.
      where w.depth < 16
    ),
    leaves as (
      select
        s.id, s.name, s.conversion_factor,
        case when w.depth = 1 and s.id = f.source_item_id then 'sale' else 'consume' end as kind,
        case when w.unit = 'pack' then 'pack' else 'base' end as mode,
        sum(w.qty) as qty
      from walk w
      join public.products s on s.id = w.product_id and s.type = 'stock'
      join public.products f on f.id = w.line_product
      group by 1, 2, 3, 4, 5
    )
    select
      id, name, kind,
      case when mode = 'pack' and qty <> trunc(qty) then 'base' else mode end as mode,
      case when mode = 'pack' and qty <> trunc(qty) then qty * coalesce(conversion_factor, 1) else qty end as qty
    from leaves
    -- Sealed packs before loose units of the same item, so a loose draw never opens the pack a pack sale
    -- was about to take.
    order by id, mode desc, kind
  loop
    begin
      perform public.draw_stock(jsonb_build_object(
        'product_id', d.id, 'qty', d.qty, 'mode', d.mode, 'kind', d.kind, 'ref', v_sale.code
      ));
    exception when check_violation then
      if sqlerrm = 'insufficient_stock' then
        raise exception 'insufficient_stock' using errcode = '23514', detail = d.name;
      end if;
      raise;
    end;
  end loop;

  return jsonb_build_object('id', v_sale.id, 'code', v_sale.code, 'total', v_sale.total,
    'tax_total', v_sale.tax_total, 'change_due', v_sale.change_due);
end;
$$;

revoke execute on function public.record_sale(jsonb) from public, anon, authenticated, service_role;
grant execute on function public.record_sale(jsonb) to authenticated;


-- 3. void_sale: every unit the sale drew goes back to the pack it came from, with a void movement each,
-- and the sale is marked void. A pack filled since — an adjustment topped it up — raises
-- pack_over_capacity rather than holding more than it can.
create or replace function public.void_sale(p_sale uuid, p_reason text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  s public.sales;
begin
  select * into s from public.sales where id = p_sale;
  if s.id is null then
    raise exception 'sale_not_found' using errcode = 'P0002';
  end if;
  perform private.assert_member(s.merchant_id);

  -- Items first, then the sale: the ledger's lock order (20260929100100_stock_ledger.sql §5).
  perform 1 from public.products
  where id in (
    select m.product_id from public.stock_movements m
    where m.merchant_id = s.merchant_id and m.ref = s.code and m.kind in ('sale', 'consume')
  )
  order by id
  for update;

  select * into s from public.sales where id = p_sale for update;
  if s.voided_at is not null then
    raise exception 'sale_voided' using errcode = '23514';
  end if;

  if exists (
    select 1 from public.stock_packs k
    join (
      select m.pack_id, -sum(m.qty) as back from public.stock_movements m
      where m.merchant_id = s.merchant_id and m.ref = s.code and m.kind in ('sale', 'consume')
      group by m.pack_id
    ) b on b.pack_id = k.id
    where k.qty_remaining + b.back > k.units
  ) then
    raise exception 'pack_over_capacity' using errcode = '23514';
  end if;

  insert into public.stock_movements (merchant_id, product_id, lot_id, pack_id, kind, qty, note, ref, created_by)
  select m.merchant_id, m.product_id, m.lot_id, m.pack_id, 'void', -m.qty, nullif(btrim(p_reason), ''),
    s.code, (select auth.uid())
  from public.stock_movements m
  where m.merchant_id = s.merchant_id and m.ref = s.code and m.kind in ('sale', 'consume');

  update public.stock_packs k set qty_remaining = k.qty_remaining + b.back
  from (
    select m.pack_id, -sum(m.qty) as back from public.stock_movements m
    where m.merchant_id = s.merchant_id and m.ref = s.code and m.kind in ('sale', 'consume')
    group by m.pack_id
  ) b
  where b.pack_id = k.id;

  update public.sales set voided_at = now(), void_reason = nullif(btrim(p_reason), '') where id = s.id;

  perform private.recompute_stock(m.product_id)
  from (
    select distinct product_id from public.stock_movements
    where merchant_id = s.merchant_id and ref = s.code and kind in ('sale', 'consume')
  ) m;
end;
$$;

revoke execute on function public.void_sale(uuid, text) from public, anon, authenticated, service_role;
grant execute on function public.void_sale(uuid, text) to authenticated;


-- 4. Policies: select only, and §2 and §3 are the only way in.
do $$
declare
  t text;
begin
  foreach t in array array['sales', 'sale_lines'] loop
    execute format('drop policy if exists %I on public.%I', t || '_select_own_merchant', t);
    execute format(
      'create policy %I on public.%I for select to authenticated
         using (merchant_id in (select private.current_merchant_ids()))',
      t || '_select_own_merchant', t
    );
  end loop;
end
$$;


-- ===== 20261001100000_category_optional.sql =====

-- Category optional on every product: a sellable face may stay uncategorised once published
-- (Products is becoming Assets, and an asset's grouping comes from Inventory's folders, not from it).
--
-- Drops products_category_required (20260929100000_stock_items.sql), which let a product go without a
-- category only as a draft or a stock item. category_id is already nullable; nothing else reads the rule.

alter table public.products drop constraint if exists products_category_required;


-- ===== 20261001110000_group_category.sql =====

-- A variant group owns its category: every item in a group is filed where the group is, so Inventory and
-- Stock can fold a group into one folder under one category.
--
-- 1. product_groups gains category_id, subcategory_id and scope, keyed to Inventory's categories.
-- 2. private.group_category_to_item: an item joining a group, or saved in one, takes the group's category.
-- 3. private.group_category_to_items: a group's category changing moves its items with it.
-- 4. save_stock_item: a group with no category takes the category of the item saved into it.
-- 5. Backfill: each existing group takes its oldest categorised item's category, and §3 aligns the rest.
--
-- The first category a group gets sticks: once it has one, an item's own pick is overwritten by §2, and
-- the Inventory form shows the field disabled. A group with no category (made from a receipt line, which
-- has no category field) takes the next categorised item saved into it.
--
-- Both triggers are security invoker. Every row they touch belongs to the caller's merchant (the group
-- key is (group_id, merchant_id)), so RLS already allows it. Rejected: security definer, which would add
-- CLAUDE.md §6.2's three obligations for no reach the caller lacks.
--
-- Deleting a category sets a group's category to null (§1), and §3 then clears it from the group's
-- items, so a category used only by grouped items can be deleted. An ungrouped item still blocks the
-- delete, as products_category_fk (NO ACTION) always has.


-- 1. Columns.
alter table public.product_groups
  add column if not exists category_id uuid,
  add column if not exists subcategory_id uuid,
  add column if not exists scope public.category_scope not null default 'inventory';

alter table public.product_groups drop constraint if exists product_groups_scope_inventory;
alter table public.product_groups drop constraint if exists product_groups_category_fk;
alter table public.product_groups drop constraint if exists product_groups_subcategory_fk;

-- Groups are Inventory's only; the scope column exists so the keys below can name it.
alter table public.product_groups
  add constraint product_groups_scope_inventory check (scope = 'inventory');
alter table public.product_groups
  add constraint product_groups_category_fk foreign key (category_id, merchant_id, scope)
    references public.product_categories (id, merchant_id, scope) on delete set null (category_id);
alter table public.product_groups
  add constraint product_groups_subcategory_fk foreign key (subcategory_id, merchant_id, scope)
    references public.product_categories (id, merchant_id, scope) on delete set null (subcategory_id);

create index if not exists product_groups_category_id_idx on public.product_groups (category_id);
create index if not exists product_groups_subcategory_id_idx on public.product_groups (subcategory_id);


-- 2. Group to item, on the item's own write.
create or replace function private.group_category_to_item()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  select g.category_id, g.subcategory_id into new.category_id, new.subcategory_id
  from public.product_groups g
  where g.id = new.group_id;
  return new;
end;
$$;

revoke execute on function private.group_category_to_item() from public, anon, authenticated, service_role;

drop trigger if exists products_group_category on public.products;
create trigger products_group_category
  before insert or update of group_id, category_id, subcategory_id on public.products
  for each row when (new.group_id is not null)
  execute function private.group_category_to_item();


-- 3. Group to its items, when the group's category changes.
create or replace function private.group_category_to_items()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  update public.products p
  set category_id = new.category_id, subcategory_id = new.subcategory_id, updated_at = now()
  where p.group_id = new.id
    and (p.category_id is distinct from new.category_id or p.subcategory_id is distinct from new.subcategory_id);
  return null;
end;
$$;

revoke execute on function private.group_category_to_items() from public, anon, authenticated, service_role;

drop trigger if exists product_groups_category_to_items on public.product_groups;
create trigger product_groups_category_to_items
  after update of category_id, subcategory_id on public.product_groups
  for each row
  when (old.category_id is distinct from new.category_id or old.subcategory_id is distinct from new.subcategory_id)
  execute function private.group_category_to_items();


-- 4. save_stock_item: as 20260929100000_stock_items.sql §7, plus a group with no category taking the
-- item's before the item is written, so §2 hands the item back the category it was saved with.
create or replace function public.save_stock_item(payload jsonb)
returns uuid
language plpgsql
security invoker
set search_path = ''
as $$
declare
  p public.products;
  v_id uuid;
  v_group uuid;
  v_group_name text := nullif(btrim(payload ->> 'group_name'), '');
begin
  p := jsonb_populate_record(null::public.products, payload -> 'item');
  v_group := p.group_id;

  if v_group is null and v_group_name is not null then
    insert into public.product_groups (merchant_id, name) values (p.merchant_id, v_group_name)
    on conflict (merchant_id, name) do update set name = excluded.name
    returning id into v_group;
  end if;

  if v_group is not null and p.category_id is not null then
    update public.product_groups
    set category_id = p.category_id, subcategory_id = p.subcategory_id
    where id = v_group and category_id is null;
  end if;

  if p.id is null then
    insert into public.products (
      merchant_id, type, name, category_id, subcategory_id, sku, barcode, description, tags, status,
      sold_directly, track_inventory, storage_location, reorder_threshold, expiry_alert_days, perishable,
      conversion_factor, pack_unit_name, base_unit_name, sell_by, stock_role, group_id, attributes,
      internal_notes
    ) values (
      p.merchant_id, 'stock', p.name, p.category_id, p.subcategory_id, p.sku, p.barcode, p.description,
      coalesce(p.tags, '{}'), coalesce(p.status, 'active'),
      false, true, p.storage_location, p.reorder_threshold, p.expiry_alert_days, coalesce(p.perishable, true),
      coalesce(p.conversion_factor, 1), p.pack_unit_name, p.base_unit_name, p.sell_by, p.stock_role, v_group,
      coalesce(p.attributes, '{}'), p.internal_notes
    )
    returning id into v_id;
  else
    update public.products set
      name = p.name, category_id = p.category_id, subcategory_id = p.subcategory_id, sku = p.sku,
      barcode = p.barcode, description = p.description, tags = coalesce(p.tags, '{}'),
      status = coalesce(p.status, status), storage_location = p.storage_location,
      reorder_threshold = p.reorder_threshold, expiry_alert_days = p.expiry_alert_days,
      perishable = coalesce(p.perishable, perishable), conversion_factor = coalesce(p.conversion_factor, 1),
      pack_unit_name = p.pack_unit_name, base_unit_name = p.base_unit_name, sell_by = p.sell_by,
      stock_role = p.stock_role, group_id = v_group, attributes = coalesce(p.attributes, '{}'),
      internal_notes = p.internal_notes, updated_at = now()
    where id = p.id and type = 'stock'
    returning id into v_id;

    if v_id is null then
      raise exception 'product_not_found' using errcode = 'P0002';
    end if;
  end if;

  if p.id is null and coalesce((payload -> 'opening' ->> 'packs')::integer, 0)
       + coalesce((payload -> 'opening' ->> 'loose_units')::numeric, 0) > 0 then
    perform public.add_inventory_stock((payload -> 'opening') || jsonb_build_object('product_id', v_id));
  end if;

  return v_id;
end;
$$;

revoke execute on function public.save_stock_item(jsonb) from public, anon, authenticated, service_role;
grant execute on function public.save_stock_item(jsonb) to authenticated;


-- 5. Backfill.
update public.product_groups g
set category_id = m.category_id, subcategory_id = m.subcategory_id
from (
  select distinct on (group_id) group_id, category_id, subcategory_id
  from public.products
  where group_id is not null and category_id is not null
  order by group_id, created_at
) m
where m.group_id = g.id and g.category_id is null;


-- ===== 20261004120000_expiry_alert_on.sql =====

-- An Inventory item's Expiry alert is a date: from that day on, its lots read Expiring. It was a day count
-- (expiry_alert_days, warn N days before each lot expires); the human chose a date on 2026-10-04.
--
-- 1. products.expiry_alert_on, a date. Null is no alert; a lot past its own expiry still reads Expired.
-- 2. save_stock_item: as 20261001110000_group_category.sql §4, writing expiry_alert_on in place of
--    expiry_alert_days.
--
-- expiry_alert_days stays. The Assets product form still writes it, and nothing backfills a date from it:
-- a day count is relative to each lot's expiry, and there is no single date it stands for. An Inventory
-- item saved before this keeps its day count unread until a date is set on it.
--
-- Rejected: keeping the day count (it follows every new delivery's expiry, where one date goes stale after
-- a restock) — the human's call, made knowing that trade-off.


-- 1. Column. Nullable with no default, so adding it rewrites nothing.
alter table public.products add column if not exists expiry_alert_on date;


-- 2. save_stock_item.
create or replace function public.save_stock_item(payload jsonb)
returns uuid
language plpgsql
security invoker
set search_path = ''
as $$
declare
  p public.products;
  v_id uuid;
  v_group uuid;
  v_group_name text := nullif(btrim(payload ->> 'group_name'), '');
begin
  p := jsonb_populate_record(null::public.products, payload -> 'item');
  v_group := p.group_id;

  if v_group is null and v_group_name is not null then
    insert into public.product_groups (merchant_id, name) values (p.merchant_id, v_group_name)
    on conflict (merchant_id, name) do update set name = excluded.name
    returning id into v_group;
  end if;

  if v_group is not null and p.category_id is not null then
    update public.product_groups
    set category_id = p.category_id, subcategory_id = p.subcategory_id
    where id = v_group and category_id is null;
  end if;

  if p.id is null then
    insert into public.products (
      merchant_id, type, name, category_id, subcategory_id, sku, barcode, description, tags, status,
      sold_directly, track_inventory, storage_location, reorder_threshold, expiry_alert_on, perishable,
      conversion_factor, pack_unit_name, base_unit_name, sell_by, stock_role, group_id, attributes,
      internal_notes
    ) values (
      p.merchant_id, 'stock', p.name, p.category_id, p.subcategory_id, p.sku, p.barcode, p.description,
      coalesce(p.tags, '{}'), coalesce(p.status, 'active'),
      false, true, p.storage_location, p.reorder_threshold, p.expiry_alert_on, coalesce(p.perishable, true),
      coalesce(p.conversion_factor, 1), p.pack_unit_name, p.base_unit_name, p.sell_by, p.stock_role, v_group,
      coalesce(p.attributes, '{}'), p.internal_notes
    )
    returning id into v_id;
  else
    update public.products set
      name = p.name, category_id = p.category_id, subcategory_id = p.subcategory_id, sku = p.sku,
      barcode = p.barcode, description = p.description, tags = coalesce(p.tags, '{}'),
      status = coalesce(p.status, status), storage_location = p.storage_location,
      reorder_threshold = p.reorder_threshold, expiry_alert_on = p.expiry_alert_on,
      perishable = coalesce(p.perishable, perishable), conversion_factor = coalesce(p.conversion_factor, 1),
      pack_unit_name = p.pack_unit_name, base_unit_name = p.base_unit_name, sell_by = p.sell_by,
      stock_role = p.stock_role, group_id = v_group, attributes = coalesce(p.attributes, '{}'),
      internal_notes = p.internal_notes, updated_at = now()
    where id = p.id and type = 'stock'
    returning id into v_id;

    if v_id is null then
      raise exception 'product_not_found' using errcode = 'P0002';
    end if;
  end if;

  if p.id is null and coalesce((payload -> 'opening' ->> 'packs')::integer, 0)
       + coalesce((payload -> 'opening' ->> 'loose_units')::numeric, 0) > 0 then
    perform public.add_inventory_stock((payload -> 'opening') || jsonb_build_object('product_id', v_id));
  end if;

  return v_id;
end;
$$;

revoke execute on function public.save_stock_item(jsonb) from public, anon, authenticated, service_role;
grant execute on function public.save_stock_item(jsonb) to authenticated;


-- ===== 20261008050254_revamp_drop_business_schema.sql =====

-- Drop the business schema: the product catalogue, suppliers, the stock ledger and the Register.
--
-- On 2026-10-08 the app was cut back to the systems list and an empty Home inside a system, ahead
-- of a rebuild on ERPNext's model. Every screen that read or wrote these objects is gone. What was
-- left behind is not inert: each table in `public` is still a PostgREST URL, and each function
-- below is still a `/rest/v1/rpc/<name>` endpoint, reachable with the publishable key that ships in
-- the app bundle, with no screen and no test behind it.
--
-- THIS DESTROYS DATA. Every row in the nineteen business tables and in private.merchant_counters,
-- and the category, address, contact_email, phone and currency of every merchant. Regenerate
-- src/lib/database.types.ts once it lands.
--
-- What stays: public.profiles with its signup trigger and delete_current_user; public.merchants as
-- id, owner_id, name and created_at, with its four owner policies; private.rls_auto_enable; and
-- private.current_merchant_ids() WITH its two grants to `authenticated` — the tenancy seam the next
-- business tables call (.claude/instruction_mds/tenancy.md §4). It goes back to having no caller, which is
-- how it started.
--
-- The order is the dependency order, because nothing here uses `cascade`: a dependent this file
-- does not name should stop it, not be taken with it. RPCs first; then private.create_lot, whose
-- signature names three tables' row types; the two views over the ledger; the tables, children
-- before parents (their policies, indexes and triggers go with them); the trigger and helper
-- functions those triggers called; the enums the columns used; and last the merchants columns the
-- name-only create form no longer writes.
--
-- `if exists` everywhere, so a clone pointed at a fresh project — which runs every earlier
-- migration first — and a project where some of this is already gone both succeed.
--
-- No revert file (.claude/instruction_mds/migrations.md rule 2): reverting would rebuild a schema no screen
-- uses, and the rows it held would not come back with it.
-- no-revert: drop-only; its revert would recreate a schema no screen uses, without its data

-- RPCs.
drop function if exists public.record_sale(payload jsonb);
drop function if exists public.void_sale(p_sale uuid, p_reason text);
drop function if exists public.void_receipt(p_receipt uuid, p_reason text);
drop function if exists public.record_stock_movement(payload jsonb);
drop function if exists public.draw_stock(payload jsonb);
drop function if exists public.add_inventory_stock(payload jsonb);
drop function if exists public.save_receipt(payload jsonb);
drop function if exists public.save_stock_item(payload jsonb);
drop function if exists public.ensure_register_faces(p_item uuid);
drop function if exists public.save_product(payload jsonb);

-- Before the tables whose row types its signature names.
drop function if exists private.create_lot(public.products, public.stock_receipts, integer, jsonb);
drop function if exists private.recompute_stock(p_product uuid);

-- The views over stock_lots and stock_packs.
drop view if exists public.stock_pick_queue;
drop view if exists public.stock_lot_lines;

-- Tables, children before parents.
drop table if exists public.sale_lines;
drop table if exists public.sales;
drop table if exists public.stock_movements;
drop table if exists public.stock_packs;
drop table if exists public.stock_cases;
drop table if exists public.stock_lots;
drop table if exists public.stock_receipts;
drop table if exists public.product_rate_tiers;
drop table if exists public.product_operating_hours;
drop table if exists public.product_variants;
drop table if exists public.product_variant_attributes;
drop table if exists public.product_components;
drop table if exists public.product_custom_fields;
drop table if exists public.products;
drop table if exists public.product_groups;
drop table if exists public.suppliers;
drop table if exists public.supplier_types;
drop table if exists public.tax_classes;
drop table if exists public.product_categories;
drop table if exists private.merchant_counters;

-- Trigger and helper functions, now attached to nothing.
drop function if exists private.assert_no_bundle_cycle();
drop function if exists private.set_product_scope();
drop function if exists private.sync_register_faces();
drop function if exists private.guard_stock_item();
drop function if exists private.group_category_to_item();
drop function if exists private.group_category_to_items();
drop function if exists private.assign_code();
drop function if exists private.assert_member(p_merchant uuid);
drop function if exists private.issue_code(p_merchant uuid, p_kind text, p_prefix text, p_width integer, p_table regclass, p_column text);
drop function if exists private.next_number(p_merchant uuid, p_kind text);

-- The enums those tables' columns used.
drop type if exists public.category_scope;
drop type if exists public.custom_field_kind;
drop type if exists public.duration_mode;
drop type if exists public.measure_unit;
drop type if exists public.product_status;
drop type if exists public.product_type;
drop type if exists public.rate_period;
drop type if exists public.stock_lot_source;
drop type if exists public.stock_movement_kind;
drop type if exists public.stock_role;
drop type if exists public.stock_sell_by;
drop type if exists public.write_off_reason;

-- The merchants columns the name-only create form no longer writes, each check before its column.
alter table public.merchants
  drop constraint if exists merchants_currency_shape,
  drop constraint if exists merchants_address_length,
  drop constraint if exists merchants_contact_email_shape,
  drop constraint if exists merchants_phone_shape,
  drop column if exists currency,
  drop column if exists address,
  drop column if exists contact_email,
  drop column if exists phone,
  drop column if exists category;

drop type if exists public.store_category;


-- ===== 20261008101635_company_and_fiscal_year.sql =====

-- Step 1 of the POS foundation, on ERPNext's model: the Company and its Fiscal Year
-- (.claude/erpnext-docs/POS-System-Only-Features.md 1.1–1.2; docs.frappe.io/erpnext/company-setup and
-- /fiscal-year).
--
-- 1. countries and currency_presets: read-only reference data a Company is set up from. Seeded from
--    frappe's geo/country_info.json (MIT, (c) Frappe Technologies), the file ERPNext itself seeds its
--    Country and Currency records from. A currency several countries define differently takes its
--    issuing country's definition (USD from the United States), else the one most countries use.
-- 2. merchants becomes the Company: abbreviation, country, default currency. Multi-company is out of
--    scope, so a system IS its company, and there is no second tenant table
--    (.claude/instruction_mds/tenancy.md rule 5).
-- 3. fiscal_years.
-- 4. The seed trigger that gives every new system its first fiscal year, as ERPNext's setup wizard does.
--
-- Re-runnable, like the rest of supabase/migrations.

create schema if not exists private;

-- The no-overlap constraint on fiscal_years compares a uuid with `=` inside a GiST index, which is what
-- btree_gist provides.
create extension if not exists btree_gist with schema extensions;


-- 1. Reference data. Readable by every signed-in user and written by nobody but a migration: RLS on,
-- with a select policy only (CLAUDE.md §6.1).

create table if not exists public.currency_presets (
  code text primary key,
  currency_name text not null,
  symbol text,
  -- The sub-unit's name for amounts in words ("Centavo"), and how many of it make one unit (100).
  fraction text,
  fraction_units integer,
  -- The smallest coin in circulation, for cash rounding. Null: round to the currency precision only.
  smallest_currency_fraction_value numeric,
  number_format text not null,

  constraint currency_presets_code_shape check (code ~ '^[A-Z]{3}$')
);

alter table public.currency_presets enable row level security;

drop policy if exists currency_presets_select on public.currency_presets;
create policy currency_presets_select on public.currency_presets
  for select to authenticated
  using (true);

create table if not exists public.countries (
  -- ISO 3166-1 alpha-2, upper case.
  code text primary key,
  country_name text not null unique,
  -- Null for the territories frappe's file gives no currency.
  currency_code text references public.currency_presets (code),
  -- IANA zones. The first is the one a new system's "today" is taken in.
  time_zones text[] not null default '{}',
  number_format text not null,

  constraint countries_code_shape check (code ~ '^[A-Z]{2}$')
);

alter table public.countries enable row level security;

drop policy if exists countries_select on public.countries;
create policy countries_select on public.countries
  for select to authenticated
  using (true);

